        {/* Bit Width Selector */}
        <div>
            <h3 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">Bus Width (Bits)</h3>
            <div className="flex flex-wrap gap-1">
                {VALID_BIT_WIDTHS.map(w => (
                    <button
                        key={w}
                        onClick={() => onSelectBitWidth(w)}
                        className={`px-2 py-1 text-xs font-bold rounded border ${selectedBitWidth === w 
                            ? 'bg-blue-100 border-blue-300 text-blue-700 shadow-sm' 
                            : 'bg-slate-50 border-slate-200 text-slate-500 hover:bg-white'}`}
                    >
                        {w}
                    </button>
                ))}
            </div>
        </div>

        {/* Components */}
        {groups.map(group => (
          <div key={group.name}>
            <h3 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">{group.name}</h3>
            <div className="grid grid-cols-2 gap-3">
              {group.items.map(type => {
                const def = COMPONENT_DEFINITIONS[type];
                const disabled = (type === ComponentType.SPLITTER || type === ComponentType.MERGER) && selectedBitWidth < 2;
                const subLabel = type === ComponentType.SPLITTER ? `${selectedBitWidth}→${selectedBitWidth/2}` : 
                                 type === ComponentType.MERGER ? `${selectedBitWidth/2}→${selectedBitWidth}` : 
                                 `x${selectedBitWidth}`;

                return (
                   <DraggableItem 
                        key={type}
                        type={type}
                        label={def.label}
                        subLabel={subLabel}
                        disabled={disabled}
                        onDragStart={(e) => !disabled && handleDragStart(e, type)}
                        onTouchStartItem={onTouchStartItem}
                   />
                );
              })}
            </div>
          </div>
        ))}

        {/* Custom Functions */}
        {draggableFunctions.length > 0 && (
            <div>
                 <h3 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">My Functions</h3>
                 <div className="grid grid-cols-1 gap-2">
                    {draggableFunctions.map(func => (
                        <DraggableItem
                            key={func.id}
                            type={ComponentType.CUSTOM_IC}
                            label={func.name}
                            subLabel=""
                            disabled={false}
                            onDragStart={(e) => handleDragStart(e, ComponentType.CUSTOM_IC, func.id)}
                            onTouchStartItem={onTouchStartItem}
                            functionId={func.id}
                            isCustom={true}
                        />
                    ))}
                 </div>
            </div>
        )}

      </div>
    </div>
  );
};

export default Sidebar;

import React, { useState, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas, { LogicCanvasHandle } from './components/LogicCanvas';
import BitViewer from './components/BitViewer';
import { ComponentType, CircuitComponent, FunctionCircuit, PortSide } from './types';
import { COMPONENT_DEFINITIONS } from './constants';
import { useProjectManager } from './hooks/useProjectManager';

const App: React.FC = () => {
  // -- UI State --
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(false);

  // Speed Control State
  const [speedSlider, setSpeedSlider] = useState(90); 
  const tickSpeed = speedSlider === 100 ? 0 : Math.max(1, 500 - (speedSlider * 5));

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newFuncName, setNewFuncName] = useState("");
  const [isProjectMenuOpen, setIsProjectMenuOpen] = useState(false);

  // -- Component Selection State --
  const [selectedComponent, setSelectedComponent] = useState<CircuitComponent | null>(null);
  const [tempLabel, setTempLabel] = useState("");

  // -- New: Bit Width Selection --
  const [selectedBitWidth, setSelectedBitWidth] = useState<number>(1);

  // -- Drag State --
  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [draggedFuncId, setDraggedFuncId] = useState<string | undefined>(undefined);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number, functionId?: string, bitWidth: number} | null>(null);

  // -- References --
  const canvasWrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<LogicCanvasHandle>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // -- Project Data Management --
  const {
      functions,
      activeFunctionId,
      activeFunction,
      lastSaved,
      dataVersion,
      switchToFunction,
      addFunction,
      deleteFunction,
      importData,
      clearData,
      persist
  } = useProjectManager(canvasRef);

  // -- Interactions --

  const handleTouchStartItem = (type: ComponentType, pos: {x: number, y: number}, functionId?: string) => {
    setDraggedType(type);
    setDraggedFuncId(functionId);
    setDragPos(pos);
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); 
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedType && dragPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left && dragPos.x <= rect.right &&
          dragPos.y >= rect.top && dragPos.y <= rect.bottom
        ) {
          setPendingDrop({ type: draggedType, x: dragPos.x - rect.left, y: dragPos.y - rect.top, functionId: draggedFuncId, bitWidth: selectedBitWidth });
        }
      }
      setDraggedType(null);
      setDraggedFuncId(undefined);
      setDragPos(null);
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }
    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, draggedFuncId, selectedBitWidth]); // Optimized deps

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const parsed = JSON.parse(e.target?.result as string);
            if (Array.isArray(parsed)) {
                if (confirm("Replace current project?")) {
                    importData(parsed, true);
                    setSelectedComponent(null);
                    setIsPlaying(false);
                }
            } else if (parsed.id) {
                importData(parsed, false);
                alert(`Imported: ${parsed.name}`);
            }
        } catch (err) { alert("Invalid File"); }
        if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsText(file);
  };

  const handleExport = (type: 'PROJECT' | 'FUNCTION') => {
      const data = type === 'PROJECT' 
        ? functions.map(f => f.id === activeFunctionId && canvasRef.current ? {...f, ...canvasRef.current.getData()} : f)
        : (canvasRef.current ? {...activeFunction, ...canvasRef.current.getData()} : activeFunction);

      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = type === 'PROJECT' ? `project.json` : `${activeFunction.name.replace(/\s+/g, '_')}.json`;
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      setIsProjectMenuOpen(false);
  };

  const createFunction = (e: React.FormEvent) => {
      e.preventDefault();
      if (newFuncName.trim()) {
          addFunction(newFuncName);
          setNewFuncName("");
          setIsModalOpen(false);
      }
  };

  const handleSelectionChange = (comp: CircuitComponent | null) => {
      setSelectedComponent(comp);
      if (comp) setTempLabel(comp.customLabel || "");
      else setTempLabel("");
  };

  const updateProp = (updates: Partial<CircuitComponent>) => {
    if (selectedComponent && canvasRef.current) {
        canvasRef.current.updateSelectedComponent(updates);
        setSelectedComponent(prev => prev ? { ...prev, ...updates } : null);
    }
  };

  // Track the ID in a ref to decouple the polling effect from selectedComponent state updates
  const selectedIdRef = useRef<string | null>(null);
  useEffect(() => { selectedIdRef.current = selectedComponent?.id || null; }, [selectedComponent]);

  // -- Live Monitor for Selected Component --
  useEffect(() => {
      if (!isPlaying) return;

      const interval = setInterval(() => {
          const currentId = selectedIdRef.current;
          if (!currentId || !canvasRef.current) return;

          const { components } = canvasRef.current.getData();
          const freshComp = components.find(c => c.id === currentId);

          if (freshComp) {
              setSelectedComponent(prev => {
                  // Guard against stale updates if selection changed
                  if (!prev || prev.id !== currentId) return prev;

                  // Deep compare key data values to avoid unnecessary re-renders
                  const prevHash = JSON.stringify({ i: prev.inputValues, o: prev.outputValues });
                  const newHash = JSON.stringify({ i: freshComp.inputValues, o: freshComp.outputValues });

                  if (prevHash !== newHash) {
                      return { ...freshComp };
                  }
                  // Return exact same object reference to prevent re-render
                  return prev;
              });
          }
      }, 100);

      return () => clearInterval(interval);
  }, [isPlaying]); 

  const handleBitToggle = (index: number) => {
      if (!selectedComponent || !canvasRef.current) return;

      const currentBus = selectedComponent.outputValues[0] || [];
      const newVal = !currentBus[index];

      canvasRef.current.setComponentOutputBit(selectedComponent.id, index, newVal);

      // Update local state immediately for responsiveness
      const newBus = [...currentBus];
      while(newBus.length <= index) newBus.push(false);
      newBus[index] = newVal;

      setSelectedComponent({ 
          ...selectedComponent, 
          outputValues: [newBus]
      });
  };

  const handleBatchBusChange = (newBus: boolean[]) => {
      if (!selectedComponent || !canvasRef.current) return;

      canvasRef.current.updateSelectedComponent({ outputValues: [newBus] });
      setSelectedComponent({ ...selectedComponent, outputValues: [newBus] });
  };

  return (
    <div className="fixed inset-0 flex bg-slate-50 text-slate-800 font-sans overflow-hidden select-none overscroll-none">
      <input type="file" ref={fileInputRef} onChange={handleFileImport} accept=".json" className="hidden" />

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={setSelectedTool}
        selectedBitWidth={selectedBitWidth}
        onSelectBitWidth={setSelectedBitWidth}
        onTouchStartItem={handleTouchStartItem}
        functionLibrary={functions}
      />

      <main className="flex-1 flex flex-col relative overflow-hidden">
        {/* HUD */}
        <div className="absolute top-4 left-4 right-4 bg-white/95 backdrop-blur shadow-sm rounded-md flex flex-wrap items-center justify-between px-4 py-2 z-10 border border-slate-200 gap-2 min-h-[50px]">

          <div className="flex items-center space-x-2">
             <div className="flex items-center bg-slate-100 rounded p-1 border border-slate-200">
               <span className="text-xs font-bold text-slate-400 px-2 hidden sm:inline">FUNC:</span>
               <select 
                 value={activeFunctionId}
                 onChange={(e) => { setIsPlaying(false); switchToFunction(e.target.value); }}
                 className="bg-transparent text-sm font-semibold text-slate-700 outline-none w-24 sm:w-32 cursor-pointer py-1"
               >
                 {functions.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
               </select>
               <button onClick={() => setIsModalOpen(true)} className="ml-2 w-8 h-8 bg-blue-100 text-blue-600 rounded hover:bg-blue-200 font-bold">+</button>
               {activeFunctionId !== 'main' && (
                 <button onClick={() => deleteFunction(activeFunctionId)} className="ml-1 w-8 h-8 bg-red-100 text-red-500 rounded hover:bg-red-200 font-bold">×</button>
               )}
             </div>

             <div className="h-5 w-px bg-slate-200 hidden sm:block"></div>

             <button 
               onClick={() => setIsPlaying(!isPlaying)}
               className="px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded text-sm font-semibold text-slate-700 w-24"
             >
               {isPlaying ? 'Pause' : 'Resume'}
             </button>

             {/* Bit Viewer Injection */}
             {selectedComponent && selectedComponent.bitWidth > 1 && (
                 <div className="hidden md:block pl-2 border-l border-slate-200">
                    <BitViewer 
                      component={selectedComponent} 
                      onToggleBit={handleBitToggle} 
                      onChangeAll={handleBatchBusChange}
                    />
                 </div>
             )}

          </div>

          <div className="flex items-center space-x-3 w-full md:w-auto justify-end">
             {selectedComponent && (
                 <div className="flex items-center space-x-2 flex-1 md:flex-none justify-center">

                     {/* Port Side Selector for Inputs/Outputs */}
                     {(selectedComponent.type === ComponentType.INPUT_SWITCH || selectedComponent.type === ComponentType.OUTPUT_LED) && (
                       <div className="flex items-center bg-slate-50 px-2 py-1 rounded border border-slate-200">
                           <span className="text-[10px] font-bold text-slate-400 mr-1 uppercase">Side</span>
                           <select 
                               value={selectedComponent.icPortSide || (selectedComponent.type === 'INPUT' ? 'right' : 'left')}
                               onChange={(e) => updateProp({ icPortSide: e.target.value as PortSide })}
                               className="bg-transparent text-xs font-semibold text-slate-700 outline-none cursor-pointer"
                           >
                               <option value="left">Left</option>
                               <option value="right">Right</option>
                               <option value="top">Top</option>
                               <option value="bottom">Bottom</option>
                           </select>
                       </div>
                     )}

                     <div className="flex items-center bg-yellow-50 px-2 py-1 rounded border border-yellow-200">
                        <input 
                            type="text" 
                            value={tempLabel}
                            onChange={(e) => { setTempLabel(e.target.value); updateProp({ customLabel: e.target.value }); }}
                            className="bg-white border border-yellow-200 text-sm px-2 py-1 rounded w-24 focus:outline-none"
                            placeholder="Label"
                        />
                     </div>
                 </div>
             )}

             <div className="relative">
                <button onClick={() => setIsProjectMenuOpen(!isProjectMenuOpen)} className="px-3 py-2 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded text-sm font-semibold text-slate-700">
                    Project ▼
                </button>
                {isProjectMenuOpen && (
                    <div className="absolute top-full left-0 mt-2 w-56 bg-white rounded-lg shadow-xl border border-slate-100 py-2 z-50 flex flex-col">
                        <div className="px-4 py-2 text-xs text-slate-400 border-b mb-1">
                            {lastSaved ? `Saved: ${lastSaved.toLocaleTimeString()}` : 'Unsaved'}
                        </div>
                        <button onClick={() => { persist(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm hover:bg-slate-50">💾 Save Now</button>
                        <button onClick={() => { fileInputRef.current?.click(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📂 Import...</button>
                        <button onClick={() => handleExport('PROJECT')} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📦 Export All</button>
                        <button onClick={() => handleExport('FUNCTION')} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📄 Export Active</button>
                        <div className="h-px bg-slate-100 my-1"></div>
                        <button onClick={() => { if(confirm("Clear all data?")) clearData(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50">🗑️ Reset</button>
                    </div>
                )}
                {isProjectMenuOpen && <div className="fixed inset-0 z-40" onClick={() => setIsProjectMenuOpen(false)}></div>}
             </div>
          </div>
        </div>

        {/* Canvas */}
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            key={`${activeFunctionId}-${dataVersion}`}
            ref={canvasRef}
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            initialComponents={activeFunction.components}
            initialWires={activeFunction.wires}
            functionLibrary={functions}
            onPendingDropHandled={() => setPendingDrop(null)}
            onSelectionChange={handleSelectionChange}
          />
        </div>

        {/* Drag Ghost */}
        {draggedType && dragPos && (
          <div className="fixed pointer-events-none z-50 opacity-80" style={{ left: dragPos.x, top: dragPos.y, transform: 'translate(-50%, -50%)' }}>
            <div className="w-12 h-12 bg-blue-100 border-2 border-blue-500 rounded flex items-center justify-center shadow-xl">
              <span className="text-[10px] font-bold text-blue-800">{draggedType === 'IC' ? 'IC' : COMPONENT_DEFINITIONS[draggedType].label}</span>
              <span className="absolute bottom-0 right-0 bg-blue-600 text-white text-[9px] px-1 rounded-tl">{selectedBitWidth}</span>
            </div>
          </div>
        )}

        {/* Modal */}
        {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden">
              <div className="bg-slate-50 px-4 py-3 border-b border-slate-100"><h3 className="font-bold">New Function</h3></div>
              <form onSubmit={createFunction} className="p-4">
                <input autoFocus type="text" value={newFuncName} onChange={(e) => setNewFuncName(e.target.value)} placeholder="Function Name" className="w-full px-3 py-2 border rounded-lg mb-4" />
                <div className="flex justify-end space-x-2">
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm font-bold text-slate-500">Cancel</button>
                  <button type="submit" className="px-4 py-2 text-sm font-bold text-white bg-blue-600 rounded-lg">Create</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import p5Types from 'p5';
import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_GRID, COLOR_WIRE_ON, COLOR_WIRE_OFF, COLOR_BUS_ON, COLOR_BUS_OFF, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE } from '../constants';

type PortPoint = { x: number, y: number, side: 'top' | 'bottom' | 'left' | 'right' };

// Helper: Convert boolean array to Hex String using BigInt to support > 31 bits
export const bitsToHex = (bits: boolean[]): string => {
  if (!bits || bits.length === 0) return "0";
  let val = 0n;
  for (let i = 0; i < bits.length; i++) {
      if (bits[i]) val |= (1n << BigInt(i));
  }
  return val.toString(16).toUpperCase();
};

export class CircuitRenderer {

  static getSide(c: CircuitComponent, isInput: boolean): PortSide {
    // For Custom ICs, we want to respect the user's side selection.
    // Default: Inputs Left, Outputs Right.
    return c.icPortSide || (isInput ? 'left' : 'right');
  }

  // --- Sorting Logic for Pins (Must match CircuitEngine) ---
  static sortICPorts(components: CircuitComponent[], isInput: boolean) {
      const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };

      return [...components].sort((a, b) => {
          const sideA = CircuitRenderer.getSide(a, isInput);
          const sideB = CircuitRenderer.getSide(b, isInput);

          if (sideOrder[sideA] !== sideOrder[sideB]) {
              return sideOrder[sideA] - sideOrder[sideB];
          }
          // Same side sorting
          if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
          return a.y - b.y;
      });
  }

  static getComponentDimensions(comp: CircuitComponent, library: FunctionCircuit[] = []) {
    const def = COMPONENT_DEFINITIONS[comp.type];

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
       const funcDef = library.find(f => f.id === comp.functionId);
       if (funcDef) {
          const inputs = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH);
          const outputs = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

          // Count ports per side
          const countSide = (list: CircuitComponent[], side: PortSide, isInput: boolean) => 
              list.filter(c => CircuitRenderer.getSide(c, isInput) === side).length;

          const topCount = countSide(inputs, 'top', true) + countSide(outputs, 'top', false);
          const bottomCount = countSide(inputs, 'bottom', true) + countSide(outputs, 'bottom', false);
          const leftCount = countSide(inputs, 'left', true) + countSide(outputs, 'left', false);
          const rightCount = countSide(inputs, 'right', true) + countSide(outputs, 'right', false);

          // Calculate Width: Max of Top/Bottom ports OR fit label name
          let width = Math.max(3, Math.max(topCount, bottomCount) + 1);

          // Estimate Label Width (Roughly)
          const nameLen = comp.customLabel ? comp.customLabel.length : (funcDef.name.length);
          const labelWidth = Math.ceil(nameLen * 0.25); // Approximate grid units
          width = Math.max(width, labelWidth + 1);

          // Calculate Height
          const height = Math.max(3, Math.max(leftCount, rightCount) + 1);

          return { w: width, h: height, inputs: inputs.length, outputs: outputs.length };
       }
       return { w: 3, h: 3, inputs: 0, outputs: 0 };
    }
    return { w: def.width, h: def.height, inputs: def.inputs, outputs: def.outputs };
  }

  static getPortPosition(comp: CircuitComponent, index: number, type: 'input' | 'output', library: FunctionCircuit[] = []): PortPoint {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;

    // 1. Dynamic pin positioning for IO (Inside function editor)
    if (comp.type === ComponentType.INPUT_SWITCH && type === 'output') {
        const side = comp.icPortSide || 'right'; // Default Output of an Switch faces Right
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }
    if (comp.type === ComponentType.OUTPUT_LED && type === 'input') {
        const side = comp.icPortSide || 'left'; // Default Input of an LED faces Left
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }

    // 2. Custom IC (Outside view)
    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
         const funcDef = library.find(f => f.id === comp.functionId);
         if (funcDef) {
             const isInput = type === 'input';
             const unsorted = isInput 
                ? funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH)
                : funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

             // Must use SAME sorting as engine
             const sorted = CircuitRenderer.sortICPorts(unsorted, isInput);
             const targetComp = sorted[index];

             if (targetComp) {
                 const side = CircuitRenderer.getSide(targetComp, isInput);

                 // Find all ports on this specific side to space them evenly
                 const inputsOnSide = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH && CircuitRenderer.getSide(c, true) === side);
                 const outputsOnSide = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED && CircuitRenderer.getSide(c, false) === side);

                 // Merge and sort them to find relative position of THIS port
                 const allOnSide = [...inputsOnSide, ...outputsOnSide];
                 // Sort based on geometric position (x or y)
                 allOnSide.sort((a, b) => {
                    if (side === 'top' || side === 'bottom') return a.x - b.x;
                    return a.y - b.y;
                 });

                 const localIndex = allOnSide.indexOf(targetComp);
                 const count = allOnSide.length;
                 const stepX = w / (count + 1);
                 const stepY = h / (count + 1);

                 if (side === 'top') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y, side: 'top' };
                 if (side === 'bottom') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y + h, side: 'bottom' };
                 if (side === 'left') return { x: comp.x, y: comp.y + ((localIndex + 1) * stepY), side: 'left' };
                 if (side === 'right') return { x: comp.x + w, y: comp.y + ((localIndex + 1) * stepY), side: 'right' };
             }
         }
    }

    // 3. Standard Components
    // Splitter
    if (comp.type === ComponentType.SPLITTER) {
        if (type === 'input') return { x: comp.x, y: comp.y + h/2, side: 'left' };
        const step = h / 3;
        return { x: comp.x + w, y: comp.y + ((index+1)*step), side: 'right' };
    }
    // Merger
    if (comp.type === ComponentType.MERGER) {
        if (type === 'output') return { x: comp.x + w, y: comp.y + h/2, side: 'right' };
        const step = h / 3;
        return { x: comp.x, y: comp.y + ((index+1)*step), side: 'left' };
    }

    // Standard Gates
    const count = type === 'input' ? dims.inputs : dims.outputs;
    const yStep = h / (count + 1);
    return {
      x: type === 'input' ? comp.x : comp.x + w,
      y: comp.y + ((index + 1) * yStep),
      side: type === 'input' ? 'left' : 'right'
    };
  }

  // --- Helpers ---

  static getWireColor(width: number, hasSignal: boolean) {
      if (width === 1) return hasSignal ? COLOR_WIRE_ON : COLOR_WIRE_OFF;
      return hasSignal ? COLOR_BUS_ON : COLOR_BUS_OFF;
  }

  static getWireWeight(width: number) {
      if (width === 1) return 3;
      if (width <= 4) return 4;
      if (width <= 16) return 5;
      if (width <= 64) return 6;
      return 7;
  }

  static isSignalActive(state: boolean[]): boolean {
      if (!state) return false;
      return state.some(b => b === true);
  }

  // --- Drawing ---

  static drawGrid(p: p5Types, viewport: { x: number, y: number, zoom: number }) {
    const visibleL = -viewport.x / viewport.zoom;
    const visibleT = -viewport.y / viewport.zoom;
    const visibleR = (p.width - viewport.x) / viewport.zoom;
    const visibleB = (p.height - viewport.y) / viewport.zoom;

    const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
    const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
    const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
    const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

    p.stroke(COLOR_GRID);
    p.strokeWeight(1 / viewport.zoom); 

    for (let x = startX; x <= endX; x += GRID_SIZE) p.line(x, visibleT, x, visibleB);
    for (let y = startY; y <= endY; y += GRID_SIZE) p.line(visibleL, y, visibleR, y);
  }

  static drawWire(p: p5Types, wire: Wire, components: CircuitComponent[], library: FunctionCircuit[]) {
      const fromComp = components.find(c => c.id === wire.fromCompId);
      const toComp = components.find(c => c.id === wire.toCompId);
      if (fromComp && toComp) {
        const start = CircuitRenderer.getPortPosition(fromComp, wire.fromPortIndex, 'output', library);
        const end = CircuitRenderer.getPortPosition(toComp, wire.toPortIndex, 'input', library);

        const active = CircuitRenderer.isSignalActive(wire.state);

        p.stroke(CircuitRenderer.getWireColor(wire.bitWidth, active));
        p.strokeWeight(CircuitRenderer.getWireWeight(wire.bitWidth));
        p.noFill();

        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        const cp2 = CircuitRenderer.getWireControlPoint(end, cpOffset);

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);

        // Label for Bus
        if (wire.bitWidth > 1) {
             const midX = p.bezierPoint(start.x, cp1.x, cp2.x, end.x, 0.5);
             const midY = p.bezierPoint(start.y, cp1.y, cp2.y, end.y, 0.5);

             p.noStroke();
             p.fill(COLOR_COMPONENT_BG);
             p.circle(midX, midY, 12);

             p.fill(COLOR_COMPONENT_STROKE);
             p.textAlign(p.CENTER, p.CENTER);
             p.textSize(8);
             p.textStyle(p.BOLD);
             p.text(wire.bitWidth, midX, midY);
             p.textStyle(p.NORMAL);
        }
      }
  }

  static drawDraftWire(p: p5Types, startInfo: { compId: string, portIndex: number, type: 'input'|'output' }, mouseWorld: {x:number, y:number}, components: CircuitComponent[], library: FunctionCircuit[]) {
      const comp = components.find(c => c.id === startInfo.compId);
      if (comp) {
        const start = CircuitRenderer.getPortPosition(comp, startInfo.portIndex, startInfo.type, library);
        p.stroke(COLOR_WIRE_OFF);
        p.strokeWeight(2);
        p.noFill();
        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        let cp2 = { x: mouseWorld.x, y: mouseWorld.y };
        if (startInfo.type === 'output') cp2 = { x: mouseWorld.x - cpOffset, y: mouseWorld.y };
        else cp2 = { x: mouseWorld.x + cpOffset, y: mouseWorld.y };

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, mouseWorld.x, mouseWorld.y);
      }
  }

  static getWireControlPoint(pt: PortPoint, offset: number) {
    if (pt.side === 'top') return { x: pt.x, y: pt.y - offset };
    if (pt.side === 'bottom') return { x: pt.x, y: pt.y + offset };
    if (pt.side === 'left') return { x: pt.x - offset, y: pt.y };
    return { x: pt.x + offset, y: pt.y };
  }

  static drawComponent(p: p5Types, comp: CircuitComponent, library: FunctionCircuit[], isSelected: boolean) {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;
    const inputs = dims.inputs;
    const outputs = dims.outputs;

    p.push();
    p.translate(comp.x, comp.y);

    // Main Draw
    if (comp.type === ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawIC(p, comp, w, h, library);
    } else if (comp.type === ComponentType.SPLITTER) {
        CircuitRenderer.drawSplitter(p, comp, w, h);
    } else if (comp.type === ComponentType.MERGER) {
        CircuitRenderer.drawMerger(p, comp, w, h);
    } else if (comp.type === ComponentType.INPUT_SWITCH) {
        CircuitRenderer.drawSwitch(p, comp, w, h);
    } else if (comp.type === ComponentType.OUTPUT_LED) {
        CircuitRenderer.drawLED(p, comp, w, h);
    } else if (comp.type === ComponentType.HEX_DISPLAY) {
        CircuitRenderer.drawHex(p, comp, w, h);
    } else {
        CircuitRenderer.drawGate(p, comp, w, h);
    }

    // Label (Only if not Custom IC, as IC draws its own label)
    if (comp.type !== ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawLabels(p, comp, w, h);
    }

    // Ports for Standard Components
    if (!['IC','INPUT','OUTPUT','HEX','SPLIT','MERGE'].includes(comp.type)) {
        p.noStroke(); p.fill('#64748b');
        for (let i = 0; i < inputs; i++) p.circle(0, ((i+1) * (h/(inputs+1))), 4);
        for (let i = 0; i < outputs; i++) p.circle(w, ((i+1) * (h/(outputs+1))), 4);
    }

    // Selection Halo
    if (isSelected) {
        p.noFill(); p.stroke('#3b82f6'); p.strokeWeight(2);
        p.rect(-4, -4, w + 8, h + 8, 4);

        // BitWidth info in corner for selected
        p.noStroke(); p.fill('#3b82f6');
        p.textSize(10); p.textAlign(p.RIGHT, p.TOP);
        p.text(`w:${comp.bitWidth}`, w + 4, h + 6);
    } else if (comp.bitWidth > 1) {
        // Always show small bitwidth indicator for buses
        p.noStroke(); p.fill('#94a3b8');
        p.textSize(9); p.textAlign(p.RIGHT, p.BOTTOM);
        p.text(comp.bitWidth, w - 2, h - 2);
    }

    p.pop();
  }

  // --- Helper: Draw Fitted Text with Ellipsis ---
  private static drawFittedText(p: p5Types, text: string, x: number, y: number, maxW: number, maxH: number) {
      let fontSize = 12; // Start larger
      const minFontSize = 8;
      p.textSize(fontSize);
      p.textAlign(p.CENTER, p.CENTER);

      let currentText = text;
      let w = p.textWidth(currentText);

      // If text fits, draw it
      if (w <= maxW) {
          p.text(currentText, x, y);
          return;
      }

      // Try shrinking font size first
      while (fontSize > minFontSize && w > maxW) {
          fontSize--;
          p.textSize(fontSize);
          w = p.textWidth(currentText);
      }

      // If still doesn't fit, truncate with ellipsis
      if (w > maxW) {
          while (currentText.length > 0 && p.textWidth(currentText + '..') > maxW) {
              currentText = currentText.slice(0, -1);
          }
          currentText += '..';
      }

      p.text(currentText, x, y);
  }

  // --- Sub-Renderers ---

  private static drawSplitter(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      // Trapezoid opening to right
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.beginShape();
      p.vertex(0, h * 0.3);
      p.vertex(w, 0);
      p.vertex(w, h);
      p.vertex(0, h * 0.7);
      p.endShape(p.CLOSE);

      // Ports
      p.fill('#64748b'); p.noStroke();
      p.circle(0, h/2, 5); // In
      const step = h/3;
      p.circle(w, step, 4); // Out 1
      p.circle(w, step*2, 4); // Out 2

      // Internal Text
      p.fill('#0f172a'); p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
      p.text("/", w/2, h/2);
  }

  private static drawMerger(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      // Trapezoid closing to right
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.beginShape();
      p.vertex(0, 0);
      p.vertex(w, h * 0.3);
      p.vertex(w, h * 0.7);
      p.vertex(0, h);
      p.endShape(p.CLOSE);

      // Ports
      p.fill('#64748b'); p.noStroke();
      const step = h/3;
      p.circle(0, step, 4); 
      p.circle(0, step*2, 4);
      p.circle(w, h/2, 5);

      p.fill('#0f172a'); p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
      p.text("&", w/2, h/2);
  }

  private static drawIC(p: p5Types, comp: CircuitComponent, w: number, h: number, library: FunctionCircuit[]) {
    // Body - slight blue tint
    p.fill('#eff6ff'); 
    p.stroke('#3b82f6'); // Blue border
    p.strokeWeight(2);
    p.rect(0, 0, w, h, 6);

    // Label
    p.fill('#1e3a8a'); 
    p.noStroke(); 
    p.textStyle(p.BOLD);

    // Draw Name
    const label = comp.customLabel || "IC";
    CircuitRenderer.drawFittedText(p, label, w/2, h/2, w - 10, h - 10);

    // Draw Ports
    if (comp.functionId) {
        const funcDef = library.find(f => f.id === comp.functionId);
        if (funcDef) {
            const inputs = CircuitRenderer.sortICPorts(funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH), true);
            const outputs = CircuitRenderer.sortICPorts(funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED), false);

            const drawPort = (c: CircuitComponent, index: number, isInput: boolean) => {
                const pt = CircuitRenderer.getPortPosition(comp, index, isInput ? 'input' : 'output', library);
                // Convert absolute to relative for drawing inside component loop
                const rx = pt.x - comp.x;
                const ry = pt.y - comp.y;

                p.fill(isInput ? '#3b82f6' : '#f59e0b');
                p.stroke('#1e293b'); p.strokeWeight(1);
                p.circle(rx, ry, 6);

                // Optional: Draw Label near port
                // p.fill('#64748b'); p.textSize(8); p.noStroke();
                // if (pt.side === 'left') { p.textAlign(p.LEFT, p.CENTER); p.text(c.customLabel || '', rx + 6, ry); }
                // else if (pt.side === 'right') { p.textAlign(p.RIGHT, p.CENTER); p.text(c.customLabel || '', rx - 6, ry); }
            };

            inputs.forEach((c, i) => drawPort(c, i, true));
            outputs.forEach((c, i) => drawPort(c, i, false));
        }
    }
  }

  private static drawSwitch(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.outputValues[0]);
      const side = comp.icPortSide || 'right';
      const boxSize = GRID_SIZE * 0.6;
      const boxOffset = (GRID_SIZE - boxSize) / 2;

      let portX = w, portY = h/2;
      if (side === 'left') { portX = 0; }
      else if (side === 'top') { portX = w/2; portY = 0; }
      else if (side === 'bottom') { portX = w/2; portY = h; }

      p.stroke(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_STROKE);
      p.strokeWeight(2);
      p.line(w/2, h/2, portX, portY);
      p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

      p.stroke(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_STROKE);
      p.fill(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_BG);
      p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);

      p.noStroke(); p.fill(isOn ? '#fff' : '#475569');

      // If bitWidth >= 16, do NOT show the value (too small). Show "16b" etc.
      if (comp.bitWidth >= 16) {
          p.textSize(9); p.textAlign(p.CENTER, p.CENTER);
          p.text(`${comp.bitWidth}b`, w/2, h/2);
      } else if (comp.bitWidth > 1) {
          // Show Hex if < 16 bits
          const hex = "0x" + bitsToHex(comp.outputValues[0] || []);
          CircuitRenderer.drawFittedText(p, hex, w/2, h/2, boxSize - 2, boxSize - 2);
      } else {
          p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
          p.text(isOn ? "1" : "0", w/2, h/2);
      }

      // Indicate direction with a small arrow/triangle if needed, or just rely on pin pos.
  }

  private static drawLED(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.inputValues[0]);
      const side = comp.icPortSide || 'left';
      const boxSize = GRID_SIZE * 0.6;
      const boxOffset = (GRID_SIZE - boxSize) / 2;

      let portX = 0, portY = h/2;
      if (side === 'right') { portX = w; }
      else if (side === 'top') { portX = w/2; portY = 0; }
      else if (side === 'bottom') { portX = w/2; portY = h; }

      p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.line(w/2, h/2, portX, portY);
      p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

      if (isOn) { p.noStroke(); p.fill(245, 158, 11, 80); p.rect(boxOffset-3, boxOffset-3, boxSize+6, boxSize+6, 6); }
      p.stroke(isOn ? COLOR_BUS_ON : '#334155');
      p.fill(isOn ? COLOR_BUS_ON : '#1e293b');
      p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);

      // Display Value or Width
      p.noStroke(); p.fill(isOn ? '#fff' : '#475569');
      if (comp.bitWidth >= 16) {
           p.textSize(9); p.textAlign(p.CENTER, p.CENTER);
           p.text(`${comp.bitWidth}b`, w/2, h/2);
      } else if (comp.bitWidth > 1) {
           const hex = "0x" + bitsToHex(comp.inputValues[0] || []);
           CircuitRenderer.drawFittedText(p, hex, w/2, h/2, boxSize - 2, boxSize - 2);
      }
  }

  private static drawHex(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const padX = 4;
      p.fill('#0f172a'); p.stroke('#334155'); p.rect(padX, 4, w - (padX*2), h-8, 4);
      p.noStroke(); p.fill('#ef4444'); 

      const hex = bitsToHex(comp.inputValues[0] || []);

      // Draw Fitted Text for Hex Display
      // Available width is (w - padX*2 - 4)
      CircuitRenderer.drawFittedText(p, hex, w/2, h/2, w - (padX*2) - 4, h - 12);

      // Port
      p.fill('#64748b'); p.circle(0, h/2, 5);
  }

  private static drawGate(p: p5Types, comp: CircuitComponent, w: number, h: number) {
    const py = 6;
    const gateW = w - 10;
    const isNegated = ['NAND', 'NOR', 'NOT'].includes(comp.type);
    const bubbleR = 4;
    let bodyW = isNegated ? gateW - (bubbleR*2) : gateW;

    p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
    p.line(gateW, h/2, w, h/2); // Out line

    if (comp.type === 'NOT') {
        p.fill(COLOR_COMPONENT_BG);
        (p as any).triangle(0, py, 0, h - py, bodyW, h / 2);
    } else {
        const isXor = comp.type === 'XOR';
        const isOrFamily = ['OR', 'NOR', 'XOR'].includes(comp.type);
        let startX = 0;

        if (isXor) {
            startX = 5;
            p.noFill();
            p.beginShape(); p.vertex(0, py); (p as any).bezierVertex(3, h * 0.33, 3, h * 0.66, 0, h - py); p.endShape();
        }

        p.fill(COLOR_COMPONENT_BG);
        p.beginShape();
        if (isOrFamily) {
            p.vertex(startX, py); p.vertex(bodyW * 0.5, py);
            (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);
            p.vertex(startX, h - py);
            (p as any).bezierVertex(startX + 5, h * 0.75, startX + 5, h * 0.25, startX, py);
        } else {
            p.vertex(0, py); p.vertex(bodyW * 0.5, py);
            (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);
            p.vertex(0, h - py); p.vertex(0, py);
        }
        p.endShape(p.CLOSE);
    }

    if (isNegated) {
        p.fill(COLOR_COMPONENT_BG); p.circle(gateW - bubbleR, h / 2, bubbleR*2);
    }
  }

  private static drawLabels(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      if (comp.customLabel && comp.type !== ComponentType.CUSTOM_IC) {
        p.noStroke(); p.fill('#1e293b'); p.textSize(12); p.textStyle(p.BOLD);
        p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2);
        p.textStyle(p.NORMAL);
      }
  }
}

import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';

/**
 * Logic Engine - Supports Multi-bit Bus Processing
 */

// Utility: Logic Ops on Arrays
const bitwiseOp = (a: boolean[], b: boolean[] | null, op: (x: boolean, y: boolean) => boolean): boolean[] => {
    const len = a.length;
    const res = new Array(len);
    for(let i=0; i<len; i++) {
        res[i] = op(a[i], b ? b[i] : false);
    }
    return res;
};

const bitwiseNot = (a: boolean[]): boolean[] => a.map(v => !v);

const evaluateLogic = (comp: CircuitComponent, inputs: boolean[][], currentOutputs: boolean[][]): boolean[][] => {
  const width = comp.bitWidth;

  // Ensure inputs have correct width (pad with false if disconnected/empty)
  const safeInput = (idx: number): boolean[] => {
     return (inputs[idx] && inputs[idx].length === width) 
        ? inputs[idx] 
        : new Array(width).fill(false);
  };

  switch (comp.type) {
    case ComponentType.INPUT_SWITCH:
      // State is maintained in outputValues[0]. 
      // If width changed, resize it (should be handled in component init, but safe to check)
      if (currentOutputs[0].length !== width) return [new Array(width).fill(false)];
      return currentOutputs;

    case ComponentType.OUTPUT_LED:
    case ComponentType.HEX_DISPLAY:
      return []; // Passive

    case ComponentType.NOT:
      return [bitwiseNot(safeInput(0))];

    case ComponentType.AND:
      return [bitwiseOp(safeInput(0), safeInput(1), (a, b) => a && b)];

    case ComponentType.OR:
      return [bitwiseOp(safeInput(0), safeInput(1), (a, b) => a || b)];

    case ComponentType.NAND:
      return [bitwiseNot(bitwiseOp(safeInput(0), safeInput(1), (a, b) => a && b))];

    case ComponentType.NOR:
      return [bitwiseNot(bitwiseOp(safeInput(0), safeInput(1), (a, b) => a || b))];

    case ComponentType.XOR:
      return [bitwiseOp(safeInput(0), safeInput(1), (a, b) => a !== b)];

    case ComponentType.SPLITTER: {
        // Input: N bits. Output: Low N/2 bits, High N/2 bits.
        // Or Top/Bottom mapping? Let's do: Output 0 (Top) = Low Bits, Output 1 (Bottom) = High Bits
        const inBus = safeInput(0);
        const half = width / 2;
        if (width < 2) return [inBus, inBus]; // Should not happen restricted by UI

        // Split array
        const low = inBus.slice(0, half);
        const high = inBus.slice(half);
        return [low, high];
    }

    case ComponentType.MERGER: {
        // Input 0 (Top) = Low Bits, Input 1 (Bottom) = High Bits -> Output N
        const half = width / 2;
        const inLow = (inputs[0] && inputs[0].length === half) ? inputs[0] : new Array(half).fill(false);
        const inHigh = (inputs[1] && inputs[1].length === half) ? inputs[1] : new Array(half).fill(false);

        return [[...inLow, ...inHigh]];
    }

    default:
      return currentOutputs;
  }
};

// Helper: Port Ordering (Must match Renderer)
const getSide = (c: CircuitComponent, isInput: boolean): PortSide => {
    return c.icPortSide || (isInput ? 'left' : 'right');
};

const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };

const sortComponents = (components: CircuitComponent[], isInput: boolean) => {
    return components.sort((a, b) => {
        const sideA = getSide(a, isInput);
        const sideB = getSide(b, isInput);

        if (sideOrder[sideA] !== sideOrder[sideB]) {
            return sideOrder[sideA] - sideOrder[sideB];
        }
        // If on same side, sort by position
        if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
        return a.y - b.y;
    });
};

// Main Step Function
export const stepSimulation = (
  currentComponents: CircuitComponent[],
  wires: Wire[],
  functionLibrary: FunctionCircuit[] = []
): { components: CircuitComponent[], wires: Wire[] } => {

  // 1. Double Buffering Setup
  const nextComponents = currentComponents.map(c => ({
    ...c,
    inputValues: c.inputValues.map(arr => [...arr]),
    outputValues: c.outputValues.map(arr => [...arr]),
    internalState: c.internalState ? {
        components: [...c.internalState.components],
        wires: [...c.internalState.wires]
    } : undefined
  }));

  const prevCompMap = new Map(currentComponents.map(c => [c.id, c]));
  const nextCompMap = new Map(nextComponents.map(c => [c.id, c]));

  // 2. Clear Inputs
  for (const comp of nextComponents) {
     comp.inputValues = []; 
  }

  // 3. Propagate Wires
  for (const wire of wires) {
    const sourceComp = prevCompMap.get(wire.fromCompId);
    const destComp = nextCompMap.get(wire.toCompId);

    if (sourceComp && destComp) {
      const sourceBus = sourceComp.outputValues[wire.fromPortIndex] || new Array(wire.bitWidth).fill(false);

      if (!destComp.inputValues[wire.toPortIndex]) {
          destComp.inputValues[wire.toPortIndex] = [...sourceBus];
      } else {
          // Bus contention: Bitwise OR
          const existing = destComp.inputValues[wire.toPortIndex];
          const combined = new Array(Math.max(existing.length, sourceBus.length));
          for(let i=0; i<combined.length; i++) {
              combined[i] = (existing[i] || false) || (sourceBus[i] || false);
          }
          destComp.inputValues[wire.toPortIndex] = combined;
      }
    }
  }

  // 4. Compute Logic
  for (const comp of nextComponents) {
    if (comp.type === ComponentType.INPUT_SWITCH) continue;

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId && comp.internalState) {
        // --- CUSTOM IC ---
        const funcDef = functionLibrary.find(f => f.id === comp.functionId);

        if (funcDef) {
            const inputsDef = sortComponents(
                funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH),
                true
            );
            const outputsDef = sortComponents(
                funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED),
                false
            );

            // Inject External -> Internal
            const internalState = comp.internalState;
            inputsDef.forEach((def, index) => {
                const internalSwitch = internalState.components.find(c => c.id === def.id);
                if (internalSwitch) {
                    // Match external bus width to internal switch width?
                    // The internal switch must be configured to match the IC Port width.
                    // For now, assume dynamic resizing or simple injection.
                    const val = comp.inputValues[index] || new Array(comp.bitWidth).fill(false);
                    internalSwitch.outputValues = [val]; 
                    internalSwitch.bitWidth = val.length; 
                }
            });

            // Step Internal
            const result = stepSimulation(internalState.components, internalState.wires, functionLibrary);
            comp.internalState = result;

            // Extract Internal -> External
            const newOutputs: boolean[][] = [];
            outputsDef.forEach((def) => {
                const internalLed = result.components.find(c => c.id === def.id);
                if (internalLed && internalLed.inputValues[0]) {
                    newOutputs.push(internalLed.inputValues[0]);
                } else {
                    newOutputs.push(new Array(comp.bitWidth).fill(false)); // Fallback
                }
            });
            comp.outputValues = newOutputs;
        }
    } else {
        comp.outputValues = evaluateLogic(comp, comp.inputValues, comp.outputValues);
    }
  }

  // 5. Update Wire Visual States
  const nextWires = wires.map(w => {
    const sourceComp = nextCompMap.get(w.fromCompId);
    let val: boolean[] = new Array(w.bitWidth).fill(false);
    if (sourceComp && sourceComp.outputValues[w.fromPortIndex]) {
        val = sourceComp.outputValues[w.fromPortIndex];
    }
    return { ...w, state: val };
  });

  return { components: nextComponents, wires: nextWires };
};

import React, { useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import p5Types from 'p5'; 
import { ComponentType, CircuitComponent, Wire, Point, FunctionCircuit } from '../types';
import { GRID_SIZE, COLOR_BG } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';
import { CircuitRenderer } from '../logic/circuitRenderer';

declare global {
  interface Window { p5: any; }
}

export interface LogicCanvasHandle {
  getData: () => { components: CircuitComponent[], wires: Wire[] };
  updateSelectedComponent: (updates: Partial<CircuitComponent>) => void;
  deleteSelected: () => void;
  setComponentOutputBit: (compId: string, bitIndex: number, value: boolean) => void;
}

interface LogicCanvasProps {
  tool: 'SELECT' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number; 
  pendingDrop?: { type: ComponentType, x: number, y: number, functionId?: string, bitWidth?: number } | null;
  initialComponents: CircuitComponent[];
  initialWires: Wire[];
  functionLibrary: FunctionCircuit[];
  onPendingDropHandled?: () => void;
  onSelectionChange?: (component: CircuitComponent | null) => void;
}

interface ViewportState {
  x: number;
  y: number;
  zoom: number;
}

const LogicCanvas = forwardRef<LogicCanvasHandle, LogicCanvasProps>(({ 
  tool, 
  isPlaying, 
  tickSpeedMs, 
  pendingDrop, 
  initialComponents,
  initialWires,
  functionLibrary,
  onPendingDropHandled,
  onSelectionChange
}, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  const componentsRef = useRef<CircuitComponent[]>(JSON.parse(JSON.stringify(initialComponents)));
  const wiresRef = useRef<Wire[]>(JSON.parse(JSON.stringify(initialWires)));

  const selectedCompId = useRef<string | null>(null);
  const activeDragId = useRef<string | null>(null);

  const viewportRef = useRef<ViewportState>({ x: 0, y: 0, zoom: 1.0 });
  const isPanningRef = useRef<boolean>(false);
  const isDraggingComp = useRef<boolean>(false);
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output', bitWidth: number } | null>(null);
  const dragOffset = useRef<Point>({ x: 0, y: 0 }); 
  const accumulatorRef = useRef<number>(0);

  const tickSpeedRef = useRef(tickSpeedMs);
  const isPlayingRef = useRef(isPlaying);
  const toolRef = useRef(tool);
  const libraryRef = useRef(functionLibrary);

  useEffect(() => { tickSpeedRef.current = tickSpeedMs; }, [tickSpeedMs]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { toolRef.current = tool; }, [tool]);
  useEffect(() => { libraryRef.current = functionLibrary; }, [functionLibrary]);

  useImperativeHandle(ref, () => ({
    getData: () => ({
        components: componentsRef.current,
        wires: wiresRef.current
    }),
    updateSelectedComponent: (updates: Partial<CircuitComponent>) => {
        if (selectedCompId.current) {
            const comp = componentsRef.current.find(c => c.id === selectedCompId.current);
            if (comp) Object.assign(comp, updates);
        }
    },
    deleteSelected: () => {
        if (selectedCompId.current) {
             const id = selectedCompId.current;
             componentsRef.current = componentsRef.current.filter(c => c.id !== id);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== id && w.toCompId !== id);
             selectedCompId.current = null;
             activeDragId.current = null;
             if(onSelectionChange) onSelectionChange(null);
        }
    },
    setComponentOutputBit: (compId: string, bitIndex: number, value: boolean) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && comp.type === ComponentType.INPUT_SWITCH) {
            // Ensure array exists and has length
            const currentBus = comp.outputValues[0] || new Array(comp.bitWidth).fill(false);
            if (currentBus.length !== comp.bitWidth) {
                // Resize if needed (rare but safe)
                while(currentBus.length < comp.bitWidth) currentBus.push(false);
            }
            const newBus = [...currentBus];
            newBus[bitIndex] = value;
            comp.outputValues[0] = newBus;
        }
    }
  }));

  const screenToWorld = (sx: number, sy: number): Point => {
    return {
      x: (sx - viewportRef.current.x) / viewportRef.current.zoom,
      y: (sy - viewportRef.current.y) / viewportRef.current.zoom
    };
  };

  const addComponent = (type: ComponentType, screenX: number, screenY: number, functionId?: string, bitWidth: number = 1) => {
    const worldPos = screenToWorld(screenX, screenY);
    const snapX = Math.round(worldPos.x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(worldPos.y / GRID_SIZE) * GRID_SIZE;

    let inputsCount = 0, outputsCount = 0, label = "", internalState = undefined;
    const def = CircuitRenderer.getComponentDimensions({ type, functionId } as any, libraryRef.current);
    inputsCount = def.inputs;
    outputsCount = def.outputs;

    if (type === ComponentType.CUSTOM_IC && functionId) {
        const func = libraryRef.current.find(f => f.id === functionId);
        if (func) {
            label = func.name;
            internalState = {
                components: JSON.parse(JSON.stringify(func.components)),
                wires: JSON.parse(JSON.stringify(func.wires))
            };
        }
    }

    const newComp: CircuitComponent = {
      id: crypto.randomUUID(),
      type: type,
      x: snapX,
      y: snapY,
      inputValues: new Array(inputsCount).fill([]), // Changed to []
      outputValues: new Array(outputsCount).fill([]), // Changed to []
      functionId: functionId,
      internalState: internalState,
      customLabel: type === ComponentType.CUSTOM_IC ? label : undefined,
      bitWidth: bitWidth
    };

    componentsRef.current.push(newComp);
    selectedCompId.current = newComp.id;
    if (onSelectionChange) onSelectionChange(newComp);
  };

  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y, pendingDrop.functionId, pendingDrop.bitWidth);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop]);

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    try {
        const data = e.dataTransfer.getData('application/react-logic-sim');
        if (data && containerRef.current) {
            const parsed = JSON.parse(data);
            const rect = containerRef.current.getBoundingClientRect();
            addComponent(parsed.type, e.clientX - rect.left, e.clientY - rect.top, parsed.functionId, parsed.bitWidth);
        }
    } catch(err) { console.error("Drop failed", err); }
  };

  // Helper to determine port width
  const getPortWidth = (comp: CircuitComponent, index: number, type: 'input'|'output'): number => {
      // Splitter Logic
      if (comp.type === ComponentType.SPLITTER) {
          if (type === 'input') return comp.bitWidth; // Input = Full Width
          return comp.bitWidth / 2; // Outputs = Half Width
      }
      // Merger Logic
      if (comp.type === ComponentType.MERGER) {
          if (type === 'output') return comp.bitWidth; // Output = Full Width
          return comp.bitWidth / 2; // Inputs = Half Width
      }
      return comp.bitWidth;
  };

  useEffect(() => {
    if (!containerRef.current || !(window as any).p5) return;
    if (p5InstanceRef.current) p5InstanceRef.current.remove();

    const sketch = (p: p5Types) => {
      // ... (Touch logic same as before, keeping brief)
      let pinchDistStart = 0;
      let lastTouchX = 0; let lastTouchY = 0; let isCanvasInteraction = false;

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        document.oncontextmenu = () => false; 
      };

      (p as any).windowResized = () => { if(containerRef.current) p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight); };

      p.draw = () => {
        p.background(COLOR_BG);

        if (isPlayingRef.current) {
          const speed = tickSpeedRef.current;
          if (speed <= 0) {
              for(let i=0; i<10; i++) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components;
                wiresRef.current = result.wires;
              }
              accumulatorRef.current = 0;
          } else {
              accumulatorRef.current += p.deltaTime;
              if (accumulatorRef.current > 500) accumulatorRef.current = 500;
              while (accumulatorRef.current >= speed) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components;
                wiresRef.current = result.wires;
                accumulatorRef.current -= speed;
              }
          }
        } else accumulatorRef.current = 0;

        p.push();
        p.translate(viewportRef.current.x, viewportRef.current.y);
        p.scale(viewportRef.current.zoom);

        CircuitRenderer.drawGrid(p, viewportRef.current);
        wiresRef.current.forEach(w => CircuitRenderer.drawWire(p, w, componentsRef.current, libraryRef.current));

        if (wiringStart.current) {
             const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
             CircuitRenderer.drawDraftWire(p, wiringStart.current, mouseWorld, componentsRef.current, libraryRef.current);
        }

        componentsRef.current.forEach(comp => {
          CircuitRenderer.drawComponent(p, comp, libraryRef.current, comp.id === selectedCompId.current);
        });

        // Hover Highlighting
        if (!activeDragId.current) {
            const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
            const hPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
            if (hPort) {
                const comp = componentsRef.current.find(c => c.id === hPort.compId);
                if (comp) {
                    const pos = CircuitRenderer.getPortPosition(comp, hPort.portIndex, hPort.type, libraryRef.current);
                    p.noFill();

                    // Logic to check validity if wiring
                    let isValid = true;
                    if (wiringStart.current) {
                        if (wiringStart.current.compId === comp.id) isValid = false; // Self
                        else if (wiringStart.current.type === hPort.type) isValid = false; // Input-Input
                        else if (wiringStart.current.bitWidth !== getPortWidth(comp, hPort.portIndex, hPort.type)) isValid = false; // Width Mismatch
                    }

                    p.stroke(isValid ? '#3b82f6' : '#ef4444'); 
                    p.strokeWeight(2);
                    p.circle(pos.x, pos.y, 14);

                    if (wiringStart.current && !isValid) {
                        p.noStroke(); p.fill('#ef4444'); p.textSize(10);
                        if (wiringStart.current.bitWidth !== getPortWidth(comp, hPort.portIndex, hPort.type)) {
                            p.text(`Width: ${getPortWidth(comp, hPort.portIndex, hPort.type)} vs ${wiringStart.current.bitWidth}`, pos.x, pos.y - 15);
                        }
                    }
                }
            }
        }

        p.pop();
      };

      const getHoveredPort = (wx: number, wy: number) => {
        const HIT_RADIUS = 12;
        for (const comp of componentsRef.current) {
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          for (let i = 0; i < dims.inputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'input', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'input' as const };
          }
          for (let i = 0; i < dims.outputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'output', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'output' as const };
          }
        }
        return null;
      };

      const getHoveredComponent = (wx: number, wy: number) => {
        for (const comp of componentsRef.current) {
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          if (wx > comp.x && wx < comp.x + (dims.w * GRID_SIZE) &&
              wy > comp.y && wy < comp.y + (dims.h * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // -- Interactions --
      (p as any).touchStarted = (e: any) => { if (e.target !== (p as any).canvas) { isCanvasInteraction = false; return true; } isCanvasInteraction = true; if (p.touches.length === 2) { const t0 = p.touches[0] as any, t1 = p.touches[1] as any; pinchDistStart = p.dist(t0.x, t0.y, t1.x, t1.y); } else if (p.touches.length === 1) { const t0 = p.touches[0] as any; lastTouchX = t0.x; lastTouchY = t0.y; p.mousePressed(undefined); } return false; };
      (p as any).touchMoved = (e: any) => { if (!isCanvasInteraction) return true; if (p.touches.length === 2) { const t0 = p.touches[0] as any, t1 = p.touches[1] as any; const currentDist = p.dist(t0.x, t0.y, t1.x, t1.y); if (pinchDistStart > 0) { const scaleFactor = currentDist / pinchDistStart; const newZoom = Math.min(Math.max(viewportRef.current.zoom * scaleFactor, 0.1), 5.0); const cx = (t0.x + t1.x) / 2, cy = (t0.y + t1.y) / 2; const wx = (cx - viewportRef.current.x) / viewportRef.current.zoom; const wy = (cy - viewportRef.current.y) / viewportRef.current.zoom; viewportRef.current.x = cx - wx * newZoom; viewportRef.current.y = cy - wy * newZoom; viewportRef.current.zoom = newZoom; pinchDistStart = currentDist; } } else if (p.touches.length === 1) { const t0 = p.touches[0] as any; if (activeDragId.current) { isDraggingComp.current = true; const mouseWorld = screenToWorld(t0.x, t0.y); const comp = componentsRef.current.find(c => c.id === activeDragId.current); if (comp) { comp.x = Math.round((mouseWorld.x - dragOffset.current.x) / GRID_SIZE) * GRID_SIZE; comp.y = Math.round((mouseWorld.y - dragOffset.current.y) / GRID_SIZE) * GRID_SIZE; } } else if (isPanningRef.current) { viewportRef.current.x += (t0.x - lastTouchX); viewportRef.current.y += (t0.y - lastTouchY); } lastTouchX = t0.x; lastTouchY = t0.y; } return false; };
      (p as any).touchEnded = () => { if (!isCanvasInteraction) return true; if (p.touches.length === 0) p.mouseReleased(); return false; };

      (p as any).mouseWheel = (e: any) => { 
        // Only zoom if hovering over the canvas
        if (e.target !== (p as any).canvas) {
            return true; 
        }

        const zoomFactor = Math.exp(-e.delta * 0.001); 
        const newZoom = Math.min(Math.max(viewportRef.current.zoom * zoomFactor, 0.1), 5.0); 
        const wx = (p.mouseX - viewportRef.current.x) / viewportRef.current.zoom; 
        const wy = (p.mouseY - viewportRef.current.y) / viewportRef.current.zoom; 
        viewportRef.current.zoom = newZoom; 
        viewportRef.current.x = p.mouseX - wx * newZoom; 
        viewportRef.current.y = p.mouseY - wy * newZoom; 
        return false; 
      };

      p.mousePressed = (e: any) => {
        if (e && e.target !== (p as any).canvas) return;
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
        isDraggingComp.current = false;
        isPanningRef.current = false;

        const port = getHoveredPort(mouseWorld.x, mouseWorld.y);
        if (port) {
            const comp = componentsRef.current.find(c => c.id === port.compId);
            if (!comp) return;

            if (port.type === 'input') {
                const existingWireIndex = wiresRef.current.findIndex(w => w.toCompId === port.compId && w.toPortIndex === port.portIndex);
                if (existingWireIndex !== -1) {
                    const existingWire = wiresRef.current[existingWireIndex];
                    wiresRef.current.splice(existingWireIndex, 1);
                    wiringStart.current = { compId: existingWire.fromCompId, portIndex: existingWire.fromPortIndex, type: 'output', bitWidth: existingWire.bitWidth };
                    return;
                }
            }
          // Get port width for starting wire
          wiringStart.current = { ...port, bitWidth: getPortWidth(comp, port.portIndex, port.type) };
          return;
        }

        const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
        if (compId) {
          if (toolRef.current === 'DELETE') {
             componentsRef.current = componentsRef.current.filter(c => c.id !== compId);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== compId && w.toCompId !== compId);
             if (selectedCompId.current === compId && onSelectionChange) onSelectionChange(null);
             if (activeDragId.current === compId) activeDragId.current = null;
             return;
          }
          const comp = componentsRef.current.find(c => c.id === compId);
          if (comp) {
             selectedCompId.current = compId;
             activeDragId.current = compId;
             dragOffset.current = { x: mouseWorld.x - comp.x, y: mouseWorld.y - comp.y };
             if (onSelectionChange) onSelectionChange(comp);
          }
          return;
        }

        selectedCompId.current = null;
        activeDragId.current = null;
        if (onSelectionChange) onSelectionChange(null);
        isPanningRef.current = true;
      };

      p.mouseDragged = () => {
        if (p.touches.length > 0) return;
        if (isPanningRef.current) {
          viewportRef.current.x += (p.mouseX - p.pmouseX);
          viewportRef.current.y += (p.mouseY - p.pmouseY);
        } else if (activeDragId.current) {
           isDraggingComp.current = true;
           const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
           const comp = componentsRef.current.find(c => c.id === activeDragId.current);
           if (comp) {
             comp.x = Math.round((mouseWorld.x - dragOffset.current.x) / GRID_SIZE) * GRID_SIZE;
             comp.y = Math.round((mouseWorld.y - dragOffset.current.y) / GRID_SIZE) * GRID_SIZE;
           }
        }
      };

      p.mouseReleased = () => {
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        // Toggle Switch Logic
        if (activeDragId.current && !isDraggingComp.current) {
          const comp = componentsRef.current.find(c => c.id === activeDragId.current);
          if (comp && comp.type === ComponentType.INPUT_SWITCH) {
              // ONLY Toggle if bitWidth is 1. For multibit, we use HUD.
              if (comp.bitWidth === 1) {
                  const currentVal = comp.outputValues[0] || [];
                  const width = comp.bitWidth;
                  const isAnyOn = currentVal.some(b => b);
                  comp.outputValues[0] = new Array(width).fill(!isAnyOn);
              }
          }
        }

        activeDragId.current = null;
        isDraggingComp.current = false;
        isPanningRef.current = false;

        if (wiringStart.current) {
          const endPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
             const endComp = componentsRef.current.find(c => c.id === endPort.compId);
             const endWidth = endComp ? getPortWidth(endComp, endPort.portIndex, endPort.type) : 0;

             // Validate Width
             if (endWidth === wiringStart.current.bitWidth) {
                let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
                let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;

                if (src.type === 'output' && dst.type === 'input') {
                  const exists = wiresRef.current.some(w => w.toCompId === dst.compId && w.toPortIndex === dst.portIndex);
                  if (!exists) {
                    wiresRef.current.push({
                      id: crypto.randomUUID(),
                      fromCompId: src.compId,
                      fromPortIndex: src.portIndex,
                      toCompId: dst.compId,
                      toPortIndex: dst.portIndex,
                      state: new Array(src.bitWidth).fill(false),
                      bitWidth: src.bitWidth
                    });
                  }
                }
             }
          }
          wiringStart.current = null;
        }
      };
    };

    p5InstanceRef.current = new (window as any).p5(sketch, containerRef.current);
    return () => { p5InstanceRef.current?.remove(); };
  }, []); 

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none pointer-events-auto" 
      onDragOver={(e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; }}
      onDrop={handleDrop}
    />
  );
});

export default LogicCanvas;

import p5Types from 'p5';
import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_GRID, COLOR_WIRE_ON, COLOR_WIRE_OFF, COLOR_BUS_ON, COLOR_BUS_OFF, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE } from '../constants';

type PortPoint = { x: number, y: number, side: 'top' | 'bottom' | 'left' | 'right' };

// Helper: Convert boolean array to Hex String using BigInt to support > 31 bits
export const bitsToHex = (bits: boolean[]): string => {
  if (!bits || bits.length === 0) return "0";
  let val = 0n;
  for (let i = 0; i < bits.length; i++) {
      if (bits[i]) val |= (1n << BigInt(i));
  }
  return val.toString(16).toUpperCase();
};

export class CircuitRenderer {

  static getSide(c: CircuitComponent, isInput: boolean): PortSide {
    // For Custom ICs, we want to respect the user's side selection.
    // Default: Inputs Left, Outputs Right.
    return c.icPortSide || (isInput ? 'left' : 'right');
  }

  // --- Sorting Logic for Pins (Must match CircuitEngine) ---
  static sortICPorts(components: CircuitComponent[], isInput: boolean) {
      const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };

      return [...components].sort((a, b) => {
          const sideA = CircuitRenderer.getSide(a, isInput);
          const sideB = CircuitRenderer.getSide(b, isInput);

          if (sideOrder[sideA] !== sideOrder[sideB]) {
              return sideOrder[sideA] - sideOrder[sideB];
          }
          // Same side sorting
          if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
          return a.y - b.y;
      });
  }

  static getComponentDimensions(comp: CircuitComponent, library: FunctionCircuit[] = []) {
    const def = COMPONENT_DEFINITIONS[comp.type];

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
       const funcDef = library.find(f => f.id === comp.functionId);
       if (funcDef) {
          const inputs = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH);
          const outputs = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

          // Count ports per side
          const countSide = (list: CircuitComponent[], side: PortSide, isInput: boolean) => 
              list.filter(c => CircuitRenderer.getSide(c, isInput) === side).length;

          const topCount = countSide(inputs, 'top', true) + countSide(outputs, 'top', false);
          const bottomCount = countSide(inputs, 'bottom', true) + countSide(outputs, 'bottom', false);
          const leftCount = countSide(inputs, 'left', true) + countSide(outputs, 'left', false);
          const rightCount = countSide(inputs, 'right', true) + countSide(outputs, 'right', false);

          // Calculate Width/Height
          // Rule: To keep ports on grid intersections (assuming standard distribution logic),
          // the dimension usually needs to be (count + 1).
          // We set a minimum of 2x2 for visual clarity.
          // We intentionally IGNORE label length to keep the IC as small as possible.

          const width = Math.max(2, Math.max(topCount, bottomCount) + 1);
          const height = Math.max(2, Math.max(leftCount, rightCount) + 1);

          return { w: width, h: height, inputs: inputs.length, outputs: outputs.length };
       }
       return { w: 2, h: 2, inputs: 0, outputs: 0 };
    }
    return { w: def.width, h: def.height, inputs: def.inputs, outputs: def.outputs };
  }

  static getPortPosition(comp: CircuitComponent, index: number, type: 'input' | 'output', library: FunctionCircuit[] = []): PortPoint {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;

    // 1. Dynamic pin positioning for IO (Inside function editor)
    if (comp.type === ComponentType.INPUT_SWITCH && type === 'output') {
        const side = comp.icPortSide || 'right'; // Default Output of an Switch faces Right
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }
    if (comp.type === ComponentType.OUTPUT_LED && type === 'input') {
        const side = comp.icPortSide || 'left'; // Default Input of an LED faces Left
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }

    // 2. Custom IC (Outside view)
    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
         const funcDef = library.find(f => f.id === comp.functionId);
         if (funcDef) {
             const isInput = type === 'input';
             const unsorted = isInput 
                ? funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH)
                : funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

             // Must use SAME sorting as engine
             const sorted = CircuitRenderer.sortICPorts(unsorted, isInput);
             const targetComp = sorted[index];

             if (targetComp) {
                 const side = CircuitRenderer.getSide(targetComp, isInput);

                 // Find all ports on this specific side to space them evenly
                 const inputsOnSide = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH && CircuitRenderer.getSide(c, true) === side);
                 const outputsOnSide = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED && CircuitRenderer.getSide(c, false) === side);

                 // Merge and sort them to find relative position of THIS port
                 const allOnSide = [...inputsOnSide, ...outputsOnSide];
                 // Sort based on geometric position (x or y)
                 allOnSide.sort((a, b) => {
                    if (side === 'top' || side === 'bottom') return a.x - b.x;
                    return a.y - b.y;
                 });

                 const localIndex = allOnSide.indexOf(targetComp);
                 const count = allOnSide.length;
                 const stepX = w / (count + 1);
                 const stepY = h / (count + 1);

                 if (side === 'top') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y, side: 'top' };
                 if (side === 'bottom') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y + h, side: 'bottom' };
                 if (side === 'left') return { x: comp.x, y: comp.y + ((localIndex + 1) * stepY), side: 'left' };
                 if (side === 'right') return { x: comp.x + w, y: comp.y + ((localIndex + 1) * stepY), side: 'right' };
             }
         }
    }

    // 3. Standard Components
    // Splitter
    if (comp.type === ComponentType.SPLITTER) {
        if (type === 'input') return { x: comp.x, y: comp.y + h/2, side: 'left' };
        const step = h / 3;
        return { x: comp.x + w, y: comp.y + ((index+1)*step), side: 'right' };
    }
    // Merger
    if (comp.type === ComponentType.MERGER) {
        if (type === 'output') return { x: comp.x + w, y: comp.y + h/2, side: 'right' };
        const step = h / 3;
        return { x: comp.x, y: comp.y + ((index+1)*step), side: 'left' };
    }

    // Standard Gates
    const count = type === 'input' ? dims.inputs : dims.outputs;
    const yStep = h / (count + 1);
    return {
      x: type === 'input' ? comp.x : comp.x + w,
      y: comp.y + ((index + 1) * yStep),
      side: type === 'input' ? 'left' : 'right'
    };
  }

  // --- Helpers ---

  static getWireColor(width: number, hasSignal: boolean) {
      if (width === 1) return hasSignal ? COLOR_WIRE_ON : COLOR_WIRE_OFF;
      return hasSignal ? COLOR_BUS_ON : COLOR_BUS_OFF;
  }

  static getWireWeight(width: number) {
      if (width === 1) return 3;
      if (width <= 4) return 4;
      if (width <= 16) return 5;
      if (width <= 64) return 6;
      return 7;
  }

  static isSignalActive(state: boolean[]): boolean {
      if (!state) return false;
      return state.some(b => b === true);
  }

  // --- Drawing ---

  static drawGrid(p: p5Types, viewport: { x: number, y: number, zoom: number }) {
    const visibleL = -viewport.x / viewport.zoom;
    const visibleT = -viewport.y / viewport.zoom;
    const visibleR = (p.width - viewport.x) / viewport.zoom;
    const visibleB = (p.height - viewport.y) / viewport.zoom;

    const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
    const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
    const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
    const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

    p.stroke(COLOR_GRID);
    p.strokeWeight(1 / viewport.zoom); 

    for (let x = startX; x <= endX; x += GRID_SIZE) p.line(x, visibleT, x, visibleB);
    for (let y = startY; y <= endY; y += GRID_SIZE) p.line(visibleL, y, visibleR, y);
  }

  static drawWire(p: p5Types, wire: Wire, components: CircuitComponent[], library: FunctionCircuit[]) {
      const fromComp = components.find(c => c.id === wire.fromCompId);
      const toComp = components.find(c => c.id === wire.toCompId);
      if (fromComp && toComp) {
        const start = CircuitRenderer.getPortPosition(fromComp, wire.fromPortIndex, 'output', library);
        const end = CircuitRenderer.getPortPosition(toComp, wire.toPortIndex, 'input', library);

        const active = CircuitRenderer.isSignalActive(wire.state);

        p.stroke(CircuitRenderer.getWireColor(wire.bitWidth, active));
        p.strokeWeight(CircuitRenderer.getWireWeight(wire.bitWidth));
        p.noFill();

        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        const cp2 = CircuitRenderer.getWireControlPoint(end, cpOffset);

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);

        // Label for Bus
        if (wire.bitWidth > 1) {
             const midX = p.bezierPoint(start.x, cp1.x, cp2.x, end.x, 0.5);
             const midY = p.bezierPoint(start.y, cp1.y, cp2.y, end.y, 0.5);

             p.noStroke();
             p.fill(COLOR_COMPONENT_BG);
             p.circle(midX, midY, 12);

             p.fill(COLOR_COMPONENT_STROKE);
             p.textAlign(p.CENTER, p.CENTER);
             p.textSize(8);
             p.textStyle(p.BOLD);
             p.text(wire.bitWidth, midX, midY);
             p.textStyle(p.NORMAL);
        }
      }
  }

  static drawDraftWire(p: p5Types, startInfo: { compId: string, portIndex: number, type: 'input'|'output' }, mouseWorld: {x:number, y:number}, components: CircuitComponent[], library: FunctionCircuit[]) {
      const comp = components.find(c => c.id === startInfo.compId);
      if (comp) {
        const start = CircuitRenderer.getPortPosition(comp, startInfo.portIndex, startInfo.type, library);
        p.stroke(COLOR_WIRE_OFF);
        p.strokeWeight(2);
        p.noFill();
        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        let cp2 = { x: mouseWorld.x, y: mouseWorld.y };
        if (startInfo.type === 'output') cp2 = { x: mouseWorld.x - cpOffset, y: mouseWorld.y };
        else cp2 = { x: mouseWorld.x + cpOffset, y: mouseWorld.y };

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, mouseWorld.x, mouseWorld.y);
      }
  }

  static getWireControlPoint(pt: PortPoint, offset: number) {
    if (pt.side === 'top') return { x: pt.x, y: pt.y - offset };
    if (pt.side === 'bottom') return { x: pt.x, y: pt.y + offset };
    if (pt.side === 'left') return { x: pt.x - offset, y: pt.y };
    return { x: pt.x + offset, y: pt.y };
  }

  static drawComponent(p: p5Types, comp: CircuitComponent, library: FunctionCircuit[], isSelected: boolean) {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;
    const inputs = dims.inputs;
    const outputs = dims.outputs;

    p.push();
    p.translate(comp.x, comp.y);

    // Main Draw
    if (comp.type === ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawIC(p, comp, w, h, library);
    } else if (comp.type === ComponentType.SPLITTER) {
        CircuitRenderer.drawSplitter(p, comp, w, h);
    } else if (comp.type === ComponentType.MERGER) {
        CircuitRenderer.drawMerger(p, comp, w, h);
    } else if (comp.type === ComponentType.INPUT_SWITCH) {
        CircuitRenderer.drawSwitch(p, comp, w, h);
    } else if (comp.type === ComponentType.OUTPUT_LED) {
        CircuitRenderer.drawLED(p, comp, w, h);
    } else if (comp.type === ComponentType.HEX_DISPLAY) {
        CircuitRenderer.drawHex(p, comp, w, h);
    } else {
        CircuitRenderer.drawGate(p, comp, w, h);
    }

    // Label (Only if not Custom IC, as IC draws its own label)
    if (comp.type !== ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawLabels(p, comp, w, h);
    }

    // Ports for Standard Components
    if (!['IC','INPUT','OUTPUT','HEX','SPLIT','MERGE'].includes(comp.type)) {
        p.noStroke(); p.fill('#64748b');
        for (let i = 0; i < inputs; i++) p.circle(0, ((i+1) * (h/(inputs+1))), 4);
        for (let i = 0; i < outputs; i++) p.circle(w, ((i+1) * (h/(outputs+1))), 4);
    }

    // Selection Halo
    if (isSelected) {
        p.noFill(); p.stroke('#3b82f6'); p.strokeWeight(2);
        p.rect(-4, -4, w + 8, h + 8, 4);

        // BitWidth info in corner for selected
        p.noStroke(); p.fill('#3b82f6');
        p.textSize(10); p.textAlign(p.RIGHT, p.TOP);
        p.text(`w:${comp.bitWidth}`, w + 4, h + 6);
    } else if (comp.bitWidth > 1) {
        // Always show small bitwidth indicator for buses
        p.noStroke(); p.fill('#94a3b8');
        p.textSize(9); p.textAlign(p.RIGHT, p.BOTTOM);
        p.text(comp.bitWidth, w - 2, h - 2);
    }

    p.pop();
  }

  // --- Helper: Draw Fitted Text with Ellipsis ---
  private static drawFittedText(p: p5Types, text: string, x: number, y: number, maxW: number, maxH: number) {
      let fontSize = 12; // Start larger
      const minFontSize = 8;
      p.textSize(fontSize);
      p.textAlign(p.CENTER, p.CENTER);

      let currentText = text;
      let w = p.textWidth(currentText);

      // If text fits, draw it
      if (w <= maxW) {
          p.text(currentText, x, y);
          return;
      }

      // Try shrinking font size first
      while (fontSize > minFontSize && w > maxW) {
          fontSize--;
          p.textSize(fontSize);
          w = p.textWidth(currentText);
      }

      // If still doesn't fit, truncate with ellipsis
      if (w > maxW) {
          while (currentText.length > 0 && p.textWidth(currentText + '..') > maxW) {
              currentText = currentText.slice(0, -1);
          }
          currentText += '..';
      }

      p.text(currentText, x, y);
  }

  // --- Sub-Renderers ---

  private static drawSplitter(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      // Trapezoid opening to right
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.beginShape();
      p.vertex(0, h * 0.3);
      p.vertex(w, 0);
      p.vertex(w, h);
      p.vertex(0, h * 0.7);
      p.endShape(p.CLOSE);

      // Ports
      p.fill('#64748b'); p.noStroke();
      p.circle(0, h/2, 5); // In
      const step = h/3;
      p.circle(w, step, 4); // Out 1
      p.circle(w, step*2, 4); // Out 2

      // Internal Text
      p.fill('#0f172a'); p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
      p.text("/", w/2, h/2);
  }

  private static drawMerger(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      // Trapezoid closing to right
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.beginShape();
      p.vertex(0, 0);
      p.vertex(w, h * 0.3);
      p.vertex(w, h * 0.7);
      p.vertex(0, h);
      p.endShape(p.CLOSE);

      // Ports
      p.fill('#64748b'); p.noStroke();
      const step = h/3;
      p.circle(0, step, 4); 
      p.circle(0, step*2, 4);
      p.circle(w, h/2, 5);

      p.fill('#0f172a'); p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
      p.text("&", w/2, h/2);
  }

  private static drawIC(p: p5Types, comp: CircuitComponent, w: number, h: number, library: FunctionCircuit[]) {
    // Body - slight blue tint
    p.fill('#eff6ff'); 
    p.stroke('#3b82f6'); // Blue border
    p.strokeWeight(2);
    p.rect(0, 0, w, h, 6);

    // Label
    p.fill('#1e3a8a'); 
    p.noStroke(); 
    p.textStyle(p.BOLD);

    // Draw Name - Allow tight fit
    const label = comp.customLabel || "IC";
    CircuitRenderer.drawFittedText(p, label, w/2, h/2, w - 4, h - 4);

    // Draw Ports
    if (comp.functionId) {
        const funcDef = library.find(f => f.id === comp.functionId);
        if (funcDef) {
            const inputs = CircuitRenderer.sortICPorts(funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH), true);
            const outputs = CircuitRenderer.sortICPorts(funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED), false);

            const drawPort = (c: CircuitComponent, index: number, isInput: boolean) => {
                const pt = CircuitRenderer.getPortPosition(comp, index, isInput ? 'input' : 'output', library);
                // Convert absolute to relative for drawing inside component loop
                const rx = pt.x - comp.x;
                const ry = pt.y - comp.y;

                p.fill(isInput ? '#3b82f6' : '#f59e0b');
                p.stroke('#1e293b'); p.strokeWeight(1);
                p.circle(rx, ry, 6);
            };

            inputs.forEach((c, i) => drawPort(c, i, true));
            outputs.forEach((c, i) => drawPort(c, i, false));
        }
    }
  }

  private static drawSwitch(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.outputValues[0]);
      const side = comp.icPortSide || 'right';
      const boxSize = GRID_SIZE * 0.6;
      const boxOffset = (GRID_SIZE - boxSize) / 2;

      let portX = w, portY = h/2;
      if (side === 'left') { portX = 0; }
      else if (side === 'top') { portX = w/2; portY = 0; }
      else if (side === 'bottom') { portX = w/2; portY = h; }

      p.stroke(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_STROKE);
      p.strokeWeight(2);
      p.line(w/2, h/2, portX, portY);
      p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

      p.stroke(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_STROKE);
      p.fill(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_BG);
      p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);

      p.noStroke(); p.fill(isOn ? '#fff' : '#475569');

      // If bitWidth >= 16, do NOT show the value (too small). Show "16b" etc.
      if (comp.bitWidth >= 16) {
          p.textSize(9); p.textAlign(p.CENTER, p.CENTER);
          p.text(`${comp.bitWidth}b`, w/2, h/2);
      } else if (comp.bitWidth > 1) {
          // Show Hex if < 16 bits
          const hex = "0x" + bitsToHex(comp.outputValues[0] || []);
          CircuitRenderer.drawFittedText(p, hex, w/2, h/2, boxSize - 2, boxSize - 2);
      } else {
          p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
          p.text(isOn ? "1" : "0", w/2, h/2);
      }

      // Indicate direction with a small arrow/triangle if needed, or just rely on pin pos.
  }

  private static drawLED(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.inputValues[0]);
      const side = comp.icPortSide || 'left';
      const boxSize = GRID_SIZE * 0.6;
      const boxOffset = (GRID_SIZE - boxSize) / 2;

      let portX = 0, portY = h/2;
      if (side === 'right') { portX = w; }
      else if (side === 'top') { portX = w/2; portY = 0; }
      else if (side === 'bottom') { portX = w/2; portY = h; }

      p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.line(w/2, h/2, portX, portY);
      p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

      if (isOn) { p.noStroke(); p.fill(245, 158, 11, 80); p.rect(boxOffset-3, boxOffset-3, boxSize+6, boxSize+6, 6); }
      p.stroke(isOn ? COLOR_BUS_ON : '#334155');
      p.fill(isOn ? COLOR_BUS_ON : '#1e293b');
      p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);

      // Display Value or Width
      p.noStroke(); p.fill(isOn ? '#fff' : '#475569');
      if (comp.bitWidth >= 16) {
           p.textSize(9); p.textAlign(p.CENTER, p.CENTER);
           p.text(`${comp.bitWidth}b`, w/2, h/2);
      } else if (comp.bitWidth > 1) {
           const hex = "0x" + bitsToHex(comp.inputValues[0] || []);
           CircuitRenderer.drawFittedText(p, hex, w/2, h/2, boxSize - 2, boxSize - 2);
      }
  }

  private static drawHex(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const padX = 4;
      p.fill('#0f172a'); p.stroke('#334155'); p.rect(padX, 4, w - (padX*2), h-8, 4);
      p.noStroke(); p.fill('#ef4444'); 

      const hex = bitsToHex(comp.inputValues[0] || []);

      // Draw Fitted Text for Hex Display
      // Available width is (w - padX*2 - 4)
      CircuitRenderer.drawFittedText(p, hex, w/2, h/2, w - (padX*2) - 4, h - 12);

      // Port
      p.fill('#64748b'); p.circle(0, h/2, 5);
  }

  private static drawGate(p: p5Types, comp: CircuitComponent, w: number, h: number) {
    const py = 6;
    const gateW = w - 10;
    const isNegated = ['NAND', 'NOR', 'NOT'].includes(comp.type);
    const bubbleR = 4;
    let bodyW = isNegated ? gateW - (bubbleR*2) : gateW;

    p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
    p.line(gateW, h/2, w, h/2); // Out line

    if (comp.type === 'NOT') {
        p.fill(COLOR_COMPONENT_BG);
        (p as any).triangle(0, py, 0, h - py, bodyW, h / 2);
    } else {
        const isXor = comp.type === 'XOR';
        const isOrFamily = ['OR', 'NOR', 'XOR'].includes(comp.type);
        let startX = 0;

        if (isXor) {
            startX = 5;
            p.noFill();
            p.beginShape(); p.vertex(0, py); (p as any).bezierVertex(3, h * 0.33, 3, h * 0.66, 0, h - py); p.endShape();
        }

        p.fill(COLOR_COMPONENT_BG);
        p.beginShape();
        if (isOrFamily) {
            p.vertex(startX, py); p.vertex(bodyW * 0.5, py);
            (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);
            p.vertex(startX, h - py);
            (p as any).bezierVertex(startX + 5, h * 0.75, startX + 5, h * 0.25, startX, py);
        } else {
            p.vertex(0, py); p.vertex(bodyW * 0.5, py);
            (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);
            p.vertex(0, h - py); p.vertex(0, py);
        }
        p.endShape(p.CLOSE);
    }

    if (isNegated) {
        p.fill(COLOR_COMPONENT_BG); p.circle(gateW - bubbleR, h / 2, bubbleR*2);
    }
  }

  private static drawLabels(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      if (comp.customLabel && comp.type !== ComponentType.CUSTOM_IC) {
        p.noStroke(); p.fill('#1e293b'); p.textSize(12); p.textStyle(p.BOLD);
        p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2);
        p.textStyle(p.NORMAL);
      }
  }
}

import p5Types from 'p5';
import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_GRID, COLOR_WIRE_ON, COLOR_WIRE_OFF, COLOR_BUS_ON, COLOR_BUS_OFF, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE } from '../constants';

type PortPoint = { x: number, y: number, side: 'top' | 'bottom' | 'left' | 'right' };

// Helper: Convert boolean array to Hex String using BigInt to support > 31 bits
export const bitsToHex = (bits: boolean[]): string => {
  if (!bits || bits.length === 0) return "0";
  let val = 0n;
  for (let i = 0; i < bits.length; i++) {
      if (bits[i]) val |= (1n << BigInt(i));
  }
  return val.toString(16).toUpperCase();
};

export class CircuitRenderer {

  static getSide(c: CircuitComponent, isInput: boolean): PortSide {
    // For Custom ICs, we want to respect the user's side selection.
    // Default: Inputs Left, Outputs Right.
    return c.icPortSide || (isInput ? 'left' : 'right');
  }

  // --- Sorting Logic for Pins (Must match CircuitEngine) ---
  static sortICPorts(components: CircuitComponent[], isInput: boolean) {
      const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };

      return [...components].sort((a, b) => {
          const sideA = CircuitRenderer.getSide(a, isInput);
          const sideB = CircuitRenderer.getSide(b, isInput);

          if (sideOrder[sideA] !== sideOrder[sideB]) {
              return sideOrder[sideA] - sideOrder[sideB];
          }
          // Same side sorting
          if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
          return a.y - b.y;
      });
  }

  static getComponentDimensions(comp: CircuitComponent, library: FunctionCircuit[] = []) {
    const def = COMPONENT_DEFINITIONS[comp.type];

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
       const funcDef = library.find(f => f.id === comp.functionId);
       if (funcDef) {
          const inputs = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH);
          const outputs = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

          // Count ports per side
          const countSide = (list: CircuitComponent[], side: PortSide, isInput: boolean) => 
              list.filter(c => CircuitRenderer.getSide(c, isInput) === side).length;

          const topCount = countSide(inputs, 'top', true) + countSide(outputs, 'top', false);
          const bottomCount = countSide(inputs, 'bottom', true) + countSide(outputs, 'bottom', false);
          const leftCount = countSide(inputs, 'left', true) + countSide(outputs, 'left', false);
          const rightCount = countSide(inputs, 'right', true) + countSide(outputs, 'right', false);

          // Calculate Width/Height
          // Rule: Min 1x1. Tighter fit based on port count.
          // If 0 or 1 port on a side, dimension is 1. If 2 ports, dimension is 2, etc.

          const width = Math.max(1, topCount, bottomCount);
          const height = Math.max(1, leftCount, rightCount);

          return { w: width, h: height, inputs: inputs.length, outputs: outputs.length };
       }
       return { w: 1, h: 1, inputs: 0, outputs: 0 };
    }
    return { w: def.width, h: def.height, inputs: def.inputs, outputs: def.outputs };
  }

  static getPortPosition(comp: CircuitComponent, index: number, type: 'input' | 'output', library: FunctionCircuit[] = []): PortPoint {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;

    // 1. Dynamic pin positioning for IO (Inside function editor)
    if (comp.type === ComponentType.INPUT_SWITCH && type === 'output') {
        const side = comp.icPortSide || 'right'; // Default Output of an Switch faces Right
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }
    if (comp.type === ComponentType.OUTPUT_LED && type === 'input') {
        const side = comp.icPortSide || 'left'; // Default Input of an LED faces Left
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }

    // 2. Custom IC (Outside view)
    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
         const funcDef = library.find(f => f.id === comp.functionId);
         if (funcDef) {
             const isInput = type === 'input';
             const unsorted = isInput 
                ? funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH)
                : funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

             // Must use SAME sorting as engine
             const sorted = CircuitRenderer.sortICPorts(unsorted, isInput);
             const targetComp = sorted[index];

             if (targetComp) {
                 const side = CircuitRenderer.getSide(targetComp, isInput);

                 // Find all ports on this specific side to space them evenly
                 const inputsOnSide = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH && CircuitRenderer.getSide(c, true) === side);
                 const outputsOnSide = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED && CircuitRenderer.getSide(c, false) === side);

                 // Merge and sort them to find relative position of THIS port
                 const allOnSide = [...inputsOnSide, ...outputsOnSide];
                 // Sort based on geometric position (x or y)
                 allOnSide.sort((a, b) => {
                    if (side === 'top' || side === 'bottom') return a.x - b.x;
                    return a.y - b.y;
                 });

                 const localIndex = allOnSide.indexOf(targetComp);
                 const count = allOnSide.length;
                 const stepX = w / (count + 1);
                 const stepY = h / (count + 1);

                 if (side === 'top') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y, side: 'top' };
                 if (side === 'bottom') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y + h, side: 'bottom' };
                 if (side === 'left') return { x: comp.x, y: comp.y + ((localIndex + 1) * stepY), side: 'left' };
                 if (side === 'right') return { x: comp.x + w, y: comp.y + ((localIndex + 1) * stepY), side: 'right' };
             }
         }
    }

    // 3. Standard Components
    // Splitter
    if (comp.type === ComponentType.SPLITTER) {
        if (type === 'input') return { x: comp.x, y: comp.y + h/2, side: 'left' };
        const step = h / 3;
        return { x: comp.x + w, y: comp.y + ((index+1)*step), side: 'right' };
    }
    // Merger
    if (comp.type === ComponentType.MERGER) {
        if (type === 'output') return { x: comp.x + w, y: comp.y + h/2, side: 'right' };
        const step = h / 3;
        return { x: comp.x, y: comp.y + ((index+1)*step), side: 'left' };
    }

    // Standard Gates
    const count = type === 'input' ? dims.inputs : dims.outputs;
    const yStep = h / (count + 1);
    return {
      x: type === 'input' ? comp.x : comp.x + w,
      y: comp.y + ((index + 1) * yStep),
      side: type === 'input' ? 'left' : 'right'
    };
  }

  // --- Helpers ---

  static getWireColor(width: number, hasSignal: boolean) {
      if (width === 1) return hasSignal ? COLOR_WIRE_ON : COLOR_WIRE_OFF;
      return hasSignal ? COLOR_BUS_ON : COLOR_BUS_OFF;
  }

  static getWireWeight(width: number) {
      if (width === 1) return 3;
      if (width <= 4) return 4;
      if (width <= 16) return 5;
      if (width <= 64) return 6;
      return 7;
  }

  static isSignalActive(state: boolean[]): boolean {
      if (!state) return false;
      return state.some(b => b === true);
  }

  // --- Drawing ---

  static drawGrid(p: p5Types, viewport: { x: number, y: number, zoom: number }) {
    const visibleL = -viewport.x / viewport.zoom;
    const visibleT = -viewport.y / viewport.zoom;
    const visibleR = (p.width - viewport.x) / viewport.zoom;
    const visibleB = (p.height - viewport.y) / viewport.zoom;

    const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
    const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
    const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
    const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

    p.stroke(COLOR_GRID);
    p.strokeWeight(1 / viewport.zoom); 

    for (let x = startX; x <= endX; x += GRID_SIZE) p.line(x, visibleT, x, visibleB);
    for (let y = startY; y <= endY; y += GRID_SIZE) p.line(visibleL, y, visibleR, y);
  }

  static drawWire(p: p5Types, wire: Wire, components: CircuitComponent[], library: FunctionCircuit[]) {
      const fromComp = components.find(c => c.id === wire.fromCompId);
      const toComp = components.find(c => c.id === wire.toCompId);
      if (fromComp && toComp) {
        const start = CircuitRenderer.getPortPosition(fromComp, wire.fromPortIndex, 'output', library);
        const end = CircuitRenderer.getPortPosition(toComp, wire.toPortIndex, 'input', library);

        const active = CircuitRenderer.isSignalActive(wire.state);

        p.stroke(CircuitRenderer.getWireColor(wire.bitWidth, active));
        p.strokeWeight(CircuitRenderer.getWireWeight(wire.bitWidth));
        p.noFill();

        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        const cp2 = CircuitRenderer.getWireControlPoint(end, cpOffset);

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);

        // Label for Bus
        if (wire.bitWidth > 1) {
             const midX = p.bezierPoint(start.x, cp1.x, cp2.x, end.x, 0.5);
             const midY = p.bezierPoint(start.y, cp1.y, cp2.y, end.y, 0.5);

             p.noStroke();
             p.fill(COLOR_COMPONENT_BG);
             p.circle(midX, midY, 12);

             p.fill(COLOR_COMPONENT_STROKE);
             p.textAlign(p.CENTER, p.CENTER);
             p.textSize(8);
             p.textStyle(p.BOLD);
             p.text(wire.bitWidth, midX, midY);
             p.textStyle(p.NORMAL);
        }
      }
  }

  static drawDraftWire(p: p5Types, startInfo: { compId: string, portIndex: number, type: 'input'|'output' }, mouseWorld: {x:number, y:number}, components: CircuitComponent[], library: FunctionCircuit[]) {
      const comp = components.find(c => c.id === startInfo.compId);
      if (comp) {
        const start = CircuitRenderer.getPortPosition(comp, startInfo.portIndex, startInfo.type, library);
        p.stroke(COLOR_WIRE_OFF);
        p.strokeWeight(2);
        p.noFill();
        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        let cp2 = { x: mouseWorld.x, y: mouseWorld.y };
        if (startInfo.type === 'output') cp2 = { x: mouseWorld.x - cpOffset, y: mouseWorld.y };
        else cp2 = { x: mouseWorld.x + cpOffset, y: mouseWorld.y };

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, mouseWorld.x, mouseWorld.y);
      }
  }

  static getWireControlPoint(pt: PortPoint, offset: number) {
    if (pt.side === 'top') return { x: pt.x, y: pt.y - offset };
    if (pt.side === 'bottom') return { x: pt.x, y: pt.y + offset };
    if (pt.side === 'left') return { x: pt.x - offset, y: pt.y };
    return { x: pt.x + offset, y: pt.y };
  }

  static drawComponent(p: p5Types, comp: CircuitComponent, library: FunctionCircuit[], isSelected: boolean) {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;
    const inputs = dims.inputs;
    const outputs = dims.outputs;

    p.push();
    p.translate(comp.x, comp.y);

    // Main Draw
    if (comp.type === ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawIC(p, comp, w, h, library);
    } else if (comp.type === ComponentType.SPLITTER) {
        CircuitRenderer.drawSplitter(p, comp, w, h);
    } else if (comp.type === ComponentType.MERGER) {
        CircuitRenderer.drawMerger(p, comp, w, h);
    } else if (comp.type === ComponentType.INPUT_SWITCH) {
        CircuitRenderer.drawSwitch(p, comp, w, h);
    } else if (comp.type === ComponentType.OUTPUT_LED) {
        CircuitRenderer.drawLED(p, comp, w, h);
    } else if (comp.type === ComponentType.HEX_DISPLAY) {
        CircuitRenderer.drawHex(p, comp, w, h);
    } else {
        CircuitRenderer.drawGate(p, comp, w, h);
    }

    // Label (Only if not Custom IC, as IC draws its own label)
    if (comp.type !== ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawLabels(p, comp, w, h);
    }

    // Ports for Standard Components
    if (!['IC','INPUT','OUTPUT','HEX','SPLIT','MERGE'].includes(comp.type)) {
        p.noStroke(); p.fill('#64748b');
        for (let i = 0; i < inputs; i++) p.circle(0, ((i+1) * (h/(inputs+1))), 4);
        for (let i = 0; i < outputs; i++) p.circle(w, ((i+1) * (h/(outputs+1))), 4);
    }

    // Selection Halo
    if (isSelected) {
        p.noFill(); p.stroke('#3b82f6'); p.strokeWeight(2);
        p.rect(-4, -4, w + 8, h + 8, 4);

        // BitWidth info in corner for selected
        p.noStroke(); p.fill('#3b82f6');
        p.textSize(10); p.textAlign(p.RIGHT, p.TOP);
        p.text(`w:${comp.bitWidth}`, w + 4, h + 6);
    } else if (comp.bitWidth > 1) {
        // Always show small bitwidth indicator for buses
        p.noStroke(); p.fill('#94a3b8');
        p.textSize(9); p.textAlign(p.RIGHT, p.BOTTOM);
        p.text(comp.bitWidth, w - 2, h - 2);
    }

    p.pop();
  }

  // --- Helper: Draw Fitted Text with Ellipsis ---
  private static drawFittedText(p: p5Types, text: string, x: number, y: number, maxW: number, maxH: number) {
      let fontSize = 12; // Start larger
      const minFontSize = 8;
      p.textSize(fontSize);
      p.textAlign(p.CENTER, p.CENTER);

      let currentText = text;
      let w = p.textWidth(currentText);

      // If text fits, draw it
      if (w <= maxW) {
          p.text(currentText, x, y);
          return;
      }

      // Try shrinking font size first
      while (fontSize > minFontSize && w > maxW) {
          fontSize--;
          p.textSize(fontSize);
          w = p.textWidth(currentText);
      }

      // If still doesn't fit, truncate with ellipsis
      if (w > maxW) {
          while (currentText.length > 0 && p.textWidth(currentText + '..') > maxW) {
              currentText = currentText.slice(0, -1);
          }
          currentText += '..';
      }

      p.text(currentText, x, y);
  }

  // --- Sub-Renderers ---

  private static drawSplitter(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      // Trapezoid opening to right
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.beginShape();
      p.vertex(0, h * 0.3);
      p.vertex(w, 0);
      p.vertex(w, h);
      p.vertex(0, h * 0.7);
      p.endShape(p.CLOSE);

      // Ports
      p.fill('#64748b'); p.noStroke();
      p.circle(0, h/2, 5); // In
      const step = h/3;
      p.circle(w, step, 4); // Out 1
      p.circle(w, step*2, 4); // Out 2

      // Internal Text
      p.fill('#0f172a'); p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
      p.text("/", w/2, h/2);
  }

  private static drawMerger(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      // Trapezoid closing to right
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.beginShape();
      p.vertex(0, 0);
      p.vertex(w, h * 0.3);
      p.vertex(w, h * 0.7);
      p.vertex(0, h);
      p.endShape(p.CLOSE);

      // Ports
      p.fill('#64748b'); p.noStroke();
      const step = h/3;
      p.circle(0, step, 4); 
      p.circle(0, step*2, 4);
      p.circle(w, h/2, 5);

      p.fill('#0f172a'); p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
      p.text("&", w/2, h/2);
  }

  private static drawIC(p: p5Types, comp: CircuitComponent, w: number, h: number, library: FunctionCircuit[]) {
    // Body - slight blue tint
    p.fill('#eff6ff'); 
    p.stroke('#3b82f6'); // Blue border
    p.strokeWeight(2);
    p.rect(0, 0, w, h, 6);

    // Label
    p.fill('#1e3a8a'); 
    p.noStroke(); 
    p.textStyle(p.BOLD);

    // Draw Name - Allow tight fit
    const label = comp.customLabel || "IC";
    CircuitRenderer.drawFittedText(p, label, w/2, h/2, w - 4, h - 4);

    // Draw Ports
    if (comp.functionId) {
        const funcDef = library.find(f => f.id === comp.functionId);
        if (funcDef) {
            const inputs = CircuitRenderer.sortICPorts(funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH), true);
            const outputs = CircuitRenderer.sortICPorts(funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED), false);

            const drawPort = (c: CircuitComponent, index: number, isInput: boolean) => {
                const pt = CircuitRenderer.getPortPosition(comp, index, isInput ? 'input' : 'output', library);
                // Convert absolute to relative for drawing inside component loop
                const rx = pt.x - comp.x;
                const ry = pt.y - comp.y;

                p.fill(isInput ? '#3b82f6' : '#f59e0b');
                p.stroke('#1e293b'); p.strokeWeight(1);
                p.circle(rx, ry, 6);
            };

            inputs.forEach((c, i) => drawPort(c, i, true));
            outputs.forEach((c, i) => drawPort(c, i, false));
        }
    }
  }

  private static drawSwitch(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.outputValues[0]);
      const side = comp.icPortSide || 'right';
      const boxSize = GRID_SIZE * 0.6;
      const boxOffset = (GRID_SIZE - boxSize) / 2;

      let portX = w, portY = h/2;
      if (side === 'left') { portX = 0; }
      else if (side === 'top') { portX = w/2; portY = 0; }
      else if (side === 'bottom') { portX = w/2; portY = h; }

      p.stroke(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_STROKE);
      p.strokeWeight(2);
      p.line(w/2, h/2, portX, portY);
      p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

      p.stroke(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_STROKE);
      p.fill(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_BG);
      p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);

      p.noStroke(); p.fill(isOn ? '#fff' : '#475569');

      // If bitWidth >= 16, do NOT show the value (too small). Show "16b" etc.
      if (comp.bitWidth >= 16) {
          p.textSize(9); p.textAlign(p.CENTER, p.CENTER);
          p.text(`${comp.bitWidth}b`, w/2, h/2);
      } else if (comp.bitWidth > 1) {
          // Show Hex if < 16 bits
          const hex = "0x" + bitsToHex(comp.outputValues[0] || []);
          CircuitRenderer.drawFittedText(p, hex, w/2, h/2, boxSize - 2, boxSize - 2);
      } else {
          p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
          p.text(isOn ? "1" : "0", w/2, h/2);
      }

      // Indicate direction with a small arrow/triangle if needed, or just rely on pin pos.
  }

  private static drawLED(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.inputValues[0]);
      const side = comp.icPortSide || 'left';
      const boxSize = GRID_SIZE * 0.6;
      const boxOffset = (GRID_SIZE - boxSize) / 2;

      let portX = 0, portY = h/2;
      if (side === 'right') { portX = w; }
      else if (side === 'top') { portX = w/2; portY = 0; }
      else if (side === 'bottom') { portX = w/2; portY = h; }

      p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.line(w/2, h/2, portX, portY);
      p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

      if (isOn) { p.noStroke(); p.fill(245, 158, 11, 80); p.rect(boxOffset-3, boxOffset-3, boxSize+6, boxSize+6, 6); }
      p.stroke(isOn ? COLOR_BUS_ON : '#334155');
      p.fill(isOn ? COLOR_BUS_ON : '#1e293b');
      p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);

      // Display Value or Width
      p.noStroke(); p.fill(isOn ? '#fff' : '#475569');
      if (comp.bitWidth >= 16) {
           p.textSize(9); p.textAlign(p.CENTER, p.CENTER);
           p.text(`${comp.bitWidth}b`, w/2, h/2);
      } else if (comp.bitWidth > 1) {
           const hex = "0x" + bitsToHex(comp.inputValues[0] || []);
           CircuitRenderer.drawFittedText(p, hex, w/2, h/2, boxSize - 2, boxSize - 2);
      }
  }

  private static drawHex(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const padX = 4;
      p.fill('#0f172a'); p.stroke('#334155'); p.rect(padX, 4, w - (padX*2), h-8, 4);
      p.noStroke(); p.fill('#ef4444'); 

      const hex = bitsToHex(comp.inputValues[0] || []);

      // Draw Fitted Text for Hex Display
      // Available width is (w - padX*2 - 4)
      CircuitRenderer.drawFittedText(p, hex, w/2, h/2, w - (padX*2) - 4, h - 12);

      // Port
      p.fill('#64748b'); p.circle(0, h/2, 5);
  }

  private static drawGate(p: p5Types, comp: CircuitComponent, w: number, h: number) {
    const py = 6;
    const gateW = w - 10;
    const isNegated = ['NAND', 'NOR', 'NOT'].includes(comp.type);
    const bubbleR = 4;
    let bodyW = isNegated ? gateW - (bubbleR*2) : gateW;

    p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
    p.line(gateW, h/2, w, h/2); // Out line

    if (comp.type === 'NOT') {
        p.fill(COLOR_COMPONENT_BG);
        (p as any).triangle(0, py, 0, h - py, bodyW, h / 2);
    } else {
        const isXor = comp.type === 'XOR';
        const isOrFamily = ['OR', 'NOR', 'XOR'].includes(comp.type);
        let startX = 0;

        if (isXor) {
            startX = 5;
            p.noFill();
            p.beginShape(); p.vertex(0, py); (p as any).bezierVertex(3, h * 0.33, 3, h * 0.66, 0, h - py); p.endShape();
        }

        p.fill(COLOR_COMPONENT_BG);
        p.beginShape();
        if (isOrFamily) {
            p.vertex(startX, py); p.vertex(bodyW * 0.5, py);
            (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);
            p.vertex(startX, h - py);
            (p as any).bezierVertex(startX + 5, h * 0.75, startX + 5, h * 0.25, startX, py);
        } else {
            p.vertex(0, py); p.vertex(bodyW * 0.5, py);
            (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);
            p.vertex(0, h - py); p.vertex(0, py);
        }
        p.endShape(p.CLOSE);
    }

    if (isNegated) {
        p.fill(COLOR_COMPONENT_BG); p.circle(gateW - bubbleR, h / 2, bubbleR*2);
    }
  }

  private static drawLabels(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      if (comp.customLabel && comp.type !== ComponentType.CUSTOM_IC) {
        p.noStroke(); p.fill('#1e293b'); p.textSize(12); p.textStyle(p.BOLD);
        p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2);
        p.textStyle(p.NORMAL);
      }
  }
}

import React, { useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import p5Types from 'p5'; 
import { ComponentType, CircuitComponent, Wire, Point, FunctionCircuit } from '../types';
import { GRID_SIZE, COLOR_BG } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';
import { CircuitRenderer } from '../logic/circuitRenderer';

declare global {
  interface Window { p5: any; }
}

export interface LogicCanvasHandle {
  getData: () => { components: CircuitComponent[], wires: Wire[] };
  updateSelectedComponent: (updates: Partial<CircuitComponent>) => void;
  deleteSelected: () => void;
  setComponentOutputBit: (compId: string, bitIndex: number, value: boolean) => void;
  focusComponent: (compId: string) => void;
}

interface LogicCanvasProps {
  tool: 'SELECT' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number; 
  pendingDrop?: { type: ComponentType, x: number, y: number, functionId?: string, bitWidth?: number } | null;
  initialComponents: CircuitComponent[];
  initialWires: Wire[];
  functionLibrary: FunctionCircuit[];
  onPendingDropHandled?: () => void;
  onSelectionChange?: (component: CircuitComponent | null) => void;
}

interface ViewportState {
  x: number;
  y: number;
  zoom: number;
}

const LogicCanvas = forwardRef<LogicCanvasHandle, LogicCanvasProps>(({ 
  tool, 
  isPlaying, 
  tickSpeedMs, 
  pendingDrop, 
  initialComponents,
  initialWires,
  functionLibrary,
  onPendingDropHandled,
  onSelectionChange
}, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  const componentsRef = useRef<CircuitComponent[]>(JSON.parse(JSON.stringify(initialComponents)));
  const wiresRef = useRef<Wire[]>(JSON.parse(JSON.stringify(initialWires)));

  const selectedCompId = useRef<string | null>(null);
  const activeDragId = useRef<string | null>(null);

  const viewportRef = useRef<ViewportState>({ x: 0, y: 0, zoom: 1.0 });
  const isPanningRef = useRef<boolean>(false);
  const isDraggingComp = useRef<boolean>(false);
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output', bitWidth: number } | null>(null);
  const dragOffset = useRef<Point>({ x: 0, y: 0 }); 
  const accumulatorRef = useRef<number>(0);

  const tickSpeedRef = useRef(tickSpeedMs);
  const isPlayingRef = useRef(isPlaying);
  const toolRef = useRef(tool);
  const libraryRef = useRef(functionLibrary);

  useEffect(() => { tickSpeedRef.current = tickSpeedMs; }, [tickSpeedMs]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { toolRef.current = tool; }, [tool]);
  useEffect(() => { libraryRef.current = functionLibrary; }, [functionLibrary]);

  useImperativeHandle(ref, () => ({
    getData: () => ({
        components: componentsRef.current,
        wires: wiresRef.current
    }),
    updateSelectedComponent: (updates: Partial<CircuitComponent>) => {
        if (selectedCompId.current) {
            const comp = componentsRef.current.find(c => c.id === selectedCompId.current);
            if (comp) Object.assign(comp, updates);
        }
    },
    deleteSelected: () => {
        if (selectedCompId.current) {
             const id = selectedCompId.current;
             componentsRef.current = componentsRef.current.filter(c => c.id !== id);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== id && w.toCompId !== id);
             selectedCompId.current = null;
             activeDragId.current = null;
             if(onSelectionChange) onSelectionChange(null);
        }
    },
    setComponentOutputBit: (compId: string, bitIndex: number, value: boolean) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && comp.type === ComponentType.INPUT_SWITCH) {
            const currentBus = comp.outputValues[0] || new Array(comp.bitWidth).fill(false);
            if (currentBus.length !== comp.bitWidth) {
                while(currentBus.length < comp.bitWidth) currentBus.push(false);
            }
            const newBus = [...currentBus];
            newBus[bitIndex] = value;
            comp.outputValues[0] = newBus;
        }
    },
    focusComponent: (compId: string) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && containerRef.current) {
             const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
             const w = dims.w * GRID_SIZE;
             const h = dims.h * GRID_SIZE;

             // Center in World
             const cx = comp.x + w/2;
             const cy = comp.y + h/2;

             // Center in Screen
             const sw = containerRef.current.clientWidth;
             const sh = containerRef.current.clientHeight;

             viewportRef.current.x = (sw/2) - (cx * viewportRef.current.zoom);
             viewportRef.current.y = (sh/2) - (cy * viewportRef.current.zoom);
        }
    }
  }));

  const screenToWorld = (sx: number, sy: number): Point => {
    return {
      x: (sx - viewportRef.current.x) / viewportRef.current.zoom,
      y: (sy - viewportRef.current.y) / viewportRef.current.zoom
    };
  };

  const addComponent = (type: ComponentType, screenX: number, screenY: number, functionId?: string, bitWidth: number = 1) => {
    const worldPos = screenToWorld(screenX, screenY);
    const snapX = Math.round(worldPos.x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(worldPos.y / GRID_SIZE) * GRID_SIZE;

    let inputsCount = 0, outputsCount = 0, label = "", internalState = undefined;
    const def = CircuitRenderer.getComponentDimensions({ type, functionId } as any, libraryRef.current);
    inputsCount = def.inputs;
    outputsCount = def.outputs;

    if (type === ComponentType.CUSTOM_IC && functionId) {
        const func = libraryRef.current.find(f => f.id === functionId);
        if (func) {
            label = func.name;
            internalState = {
                components: JSON.parse(JSON.stringify(func.components)),
                wires: JSON.parse(JSON.stringify(func.wires))
            };
        }
    }

    const newComp: CircuitComponent = {
      id: crypto.randomUUID(),
      type: type,
      x: snapX,
      y: snapY,
      inputValues: new Array(inputsCount).fill([]), 
      outputValues: new Array(outputsCount).fill([]), 
      functionId: functionId,
      internalState: internalState,
      customLabel: type === ComponentType.CUSTOM_IC ? label : undefined,
      bitWidth: bitWidth
    };

    componentsRef.current.push(newComp);
    selectedCompId.current = newComp.id;
    if (onSelectionChange) onSelectionChange(newComp);
  };

  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y, pendingDrop.functionId, pendingDrop.bitWidth);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop]);

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    try {
        const data = e.dataTransfer.getData('application/react-logic-sim');
        if (data && containerRef.current) {
            const parsed = JSON.parse(data);
            const rect = containerRef.current.getBoundingClientRect();
            addComponent(parsed.type, e.clientX - rect.left, e.clientY - rect.top, parsed.functionId, parsed.bitWidth);
        }
    } catch(err) { console.error("Drop failed", err); }
  };

  // Helper to determine port width
  const getPortWidth = (comp: CircuitComponent, index: number, type: 'input'|'output'): number => {
      // Splitter Logic
      if (comp.type === ComponentType.SPLITTER) {
          if (type === 'input') return comp.bitWidth; // Input = Full Width
          return comp.bitWidth / 2; // Outputs = Half Width
      }
      // Merger Logic
      if (comp.type === ComponentType.MERGER) {
          if (type === 'output') return comp.bitWidth; // Output = Full Width
          return comp.bitWidth / 2; // Inputs = Half Width
      }
      return comp.bitWidth;
  };

  useEffect(() => {
    if (!containerRef.current || !(window as any).p5) return;
    if (p5InstanceRef.current) p5InstanceRef.current.remove();

    const sketch = (p: p5Types) => {
      let pinchDistStart = 0;
      let lastTouchX = 0; let lastTouchY = 0; let isCanvasInteraction = false;

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        document.oncontextmenu = () => false; 
      };

      (p as any).windowResized = () => { if(containerRef.current) p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight); };

      p.draw = () => {
        p.background(COLOR_BG);

        if (isPlayingRef.current) {
          const speed = tickSpeedRef.current;
          if (speed <= 0) {
              for(let i=0; i<10; i++) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components;
                wiresRef.current = result.wires;
              }
              accumulatorRef.current = 0;
          } else {
              accumulatorRef.current += p.deltaTime;
              if (accumulatorRef.current > 500) accumulatorRef.current = 500;
              while (accumulatorRef.current >= speed) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components;
                wiresRef.current = result.wires;
                accumulatorRef.current -= speed;
              }
          }
        } else accumulatorRef.current = 0;

        p.push();
        p.translate(viewportRef.current.x, viewportRef.current.y);
        p.scale(viewportRef.current.zoom);

        CircuitRenderer.drawGrid(p, viewportRef.current);
        wiresRef.current.forEach(w => CircuitRenderer.drawWire(p, w, componentsRef.current, libraryRef.current));

        if (wiringStart.current) {
             const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
             CircuitRenderer.drawDraftWire(p, wiringStart.current, mouseWorld, componentsRef.current, libraryRef.current);
        }

        componentsRef.current.forEach(comp => {
          CircuitRenderer.drawComponent(p, comp, libraryRef.current, comp.id === selectedCompId.current);
        });

        // Hover Highlighting
        if (!activeDragId.current) {
            const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
            const hPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
            if (hPort) {
                const comp = componentsRef.current.find(c => c.id === hPort.compId);
                if (comp) {
                    const pos = CircuitRenderer.getPortPosition(comp, hPort.portIndex, hPort.type, libraryRef.current);
                    p.noFill();

                    // Logic to check validity if wiring
                    let isValid = true;
                    if (wiringStart.current) {
                        if (wiringStart.current.compId === comp.id) isValid = false; // Self
                        else if (wiringStart.current.type === hPort.type) isValid = false; // Input-Input
                        else if (wiringStart.current.bitWidth !== getPortWidth(comp, hPort.portIndex, hPort.type)) isValid = false; // Width Mismatch
                    }

                    p.stroke(isValid ? '#3b82f6' : '#ef4444'); 
                    p.strokeWeight(2);
                    p.circle(pos.x, pos.y, 14);

                    if (wiringStart.current && !isValid) {
                        p.noStroke(); p.fill('#ef4444'); p.textSize(10);
                        if (wiringStart.current.bitWidth !== getPortWidth(comp, hPort.portIndex, hPort.type)) {
                            p.text(`Width: ${getPortWidth(comp, hPort.portIndex, hPort.type)} vs ${wiringStart.current.bitWidth}`, pos.x, pos.y - 15);
                        }
                    }
                }
            }
        }

        p.pop();
      };

      const getHoveredPort = (wx: number, wy: number) => {
        const HIT_RADIUS = 12;
        for (const comp of componentsRef.current) {
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          for (let i = 0; i < dims.inputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'input', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'input' as const };
          }
          for (let i = 0; i < dims.outputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'output', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'output' as const };
          }
        }
        return null;
      };

      const getHoveredComponent = (wx: number, wy: number) => {
        for (const comp of componentsRef.current) {
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          if (wx > comp.x && wx < comp.x + (dims.w * GRID_SIZE) &&
              wy > comp.y && wy < comp.y + (dims.h * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // -- Interactions --
      (p as any).touchStarted = (e: any) => { if (e.target !== (p as any).canvas) { isCanvasInteraction = false; return true; } isCanvasInteraction = true; if (p.touches.length === 2) { const t0 = p.touches[0] as any, t1 = p.touches[1] as any; pinchDistStart = p.dist(t0.x, t0.y, t1.x, t1.y); } else if (p.touches.length === 1) { const t0 = p.touches[0] as any; lastTouchX = t0.x; lastTouchY = t0.y; p.mousePressed(undefined); } return false; };
      (p as any).touchMoved = (e: any) => { if (!isCanvasInteraction) return true; if (p.touches.length === 2) { const t0 = p.touches[0] as any, t1 = p.touches[1] as any; const currentDist = p.dist(t0.x, t0.y, t1.x, t1.y); if (pinchDistStart > 0) { const scaleFactor = currentDist / pinchDistStart; const newZoom = Math.min(Math.max(viewportRef.current.zoom * scaleFactor, 0.1), 5.0); const cx = (t0.x + t1.x) / 2, cy = (t0.y + t1.y) / 2; const wx = (cx - viewportRef.current.x) / viewportRef.current.zoom; const wy = (cy - viewportRef.current.y) / viewportRef.current.zoom; viewportRef.current.x = cx - wx * newZoom; viewportRef.current.y = cy - wy * newZoom; viewportRef.current.zoom = newZoom; pinchDistStart = currentDist; } } else if (p.touches.length === 1) { const t0 = p.touches[0] as any; if (activeDragId.current) { isDraggingComp.current = true; const mouseWorld = screenToWorld(t0.x, t0.y); const comp = componentsRef.current.find(c => c.id === activeDragId.current); if (comp) { comp.x = Math.round((mouseWorld.x - dragOffset.current.x) / GRID_SIZE) * GRID_SIZE; comp.y = Math.round((mouseWorld.y - dragOffset.current.y) / GRID_SIZE) * GRID_SIZE; } } else if (isPanningRef.current) { viewportRef.current.x += (t0.x - lastTouchX); viewportRef.current.y += (t0.y - lastTouchY); } lastTouchX = t0.x; lastTouchY = t0.y; } return false; };
      (p as any).touchEnded = () => { if (!isCanvasInteraction) return true; if (p.touches.length === 0) p.mouseReleased(); return false; };

      (p as any).mouseWheel = (e: any) => { 
        if (e.target !== (p as any).canvas) {
            return true; 
        }

        const zoomFactor = Math.exp(-e.delta * 0.001); 
        const newZoom = Math.min(Math.max(viewportRef.current.zoom * zoomFactor, 0.1), 5.0); 
        const wx = (p.mouseX - viewportRef.current.x) / viewportRef.current.zoom; 
        const wy = (p.mouseY - viewportRef.current.y) / viewportRef.current.zoom; 
        viewportRef.current.zoom = newZoom; 
        viewportRef.current.x = p.mouseX - wx * newZoom; 
        viewportRef.current.y = p.mouseY - wy * newZoom; 
        return false; 
      };

      p.mousePressed = (e: any) => {
        if (e && e.target !== (p as any).canvas) return;
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
        isDraggingComp.current = false;
        isPanningRef.current = false;

        const port = getHoveredPort(mouseWorld.x, mouseWorld.y);
        if (port) {
            const comp = componentsRef.current.find(c => c.id === port.compId);
            if (!comp) return;

            if (port.type === 'input') {
                const existingWireIndex = wiresRef.current.findIndex(w => w.toCompId === port.compId && w.toPortIndex === port.portIndex);
                if (existingWireIndex !== -1) {
                    const existingWire = wiresRef.current[existingWireIndex];
                    wiresRef.current.splice(existingWireIndex, 1);
                    wiringStart.current = { compId: existingWire.fromCompId, portIndex: existingWire.fromPortIndex, type: 'output', bitWidth: existingWire.bitWidth };
                    return;
                }
            }
          wiringStart.current = { ...port, bitWidth: getPortWidth(comp, port.portIndex, port.type) };
          return;
        }

        const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
        if (compId) {
          if (toolRef.current === 'DELETE') {
             componentsRef.current = componentsRef.current.filter(c => c.id !== compId);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== compId && w.toCompId !== compId);
             if (selectedCompId.current === compId && onSelectionChange) onSelectionChange(null);
             if (activeDragId.current === compId) activeDragId.current = null;
             return;
          }
          const comp = componentsRef.current.find(c => c.id === compId);
          if (comp) {
             selectedCompId.current = compId;
             activeDragId.current = compId;
             dragOffset.current = { x: mouseWorld.x - comp.x, y: mouseWorld.y - comp.y };
             if (onSelectionChange) onSelectionChange(comp);
          }
          return;
        }

        selectedCompId.current = null;
        activeDragId.current = null;
        if (onSelectionChange) onSelectionChange(null);
        isPanningRef.current = true;
      };

      p.mouseDragged = () => {
        if (p.touches.length > 0) return;
        if (isPanningRef.current) {
          viewportRef.current.x += (p.mouseX - p.pmouseX);
          viewportRef.current.y += (p.mouseY - p.pmouseY);
        } else if (activeDragId.current) {
           isDraggingComp.current = true;
           const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
           const comp = componentsRef.current.find(c => c.id === activeDragId.current);
           if (comp) {
             comp.x = Math.round((mouseWorld.x - dragOffset.current.x) / GRID_SIZE) * GRID_SIZE;
             comp.y = Math.round((mouseWorld.y - dragOffset.current.y) / GRID_SIZE) * GRID_SIZE;
           }
        }
      };

      p.mouseReleased = () => {
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        if (activeDragId.current && !isDraggingComp.current) {
          const comp = componentsRef.current.find(c => c.id === activeDragId.current);
          if (comp && comp.type === ComponentType.INPUT_SWITCH) {
              if (comp.bitWidth === 1) {
                  const currentVal = comp.outputValues[0] || [];
                  const width = comp.bitWidth;
                  const isAnyOn = currentVal.some(b => b);
                  comp.outputValues[0] = new Array(width).fill(!isAnyOn);
              }
          }
        }

        activeDragId.current = null;
        isDraggingComp.current = false;
        isPanningRef.current = false;

        if (wiringStart.current) {
          const endPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
             const endComp = componentsRef.current.find(c => c.id === endPort.compId);
             const endWidth = endComp ? getPortWidth(endComp, endPort.portIndex, endPort.type) : 0;

             if (endWidth === wiringStart.current.bitWidth) {
                let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
                let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;

                if (src.type === 'output' && dst.type === 'input') {
                  const exists = wiresRef.current.some(w => w.toCompId === dst.compId && w.toPortIndex === dst.portIndex);
                  if (!exists) {
                    wiresRef.current.push({
                      id: crypto.randomUUID(),
                      fromCompId: src.compId,
                      fromPortIndex: src.portIndex,
                      toCompId: dst.compId,
                      toPortIndex: dst.portIndex,
                      state: new Array(src.bitWidth).fill(false),
                      bitWidth: src.bitWidth
                    });
                  }
                }
             }
          }
          wiringStart.current = null;
        }
      };
    };

    p5InstanceRef.current = new (window as any).p5(sketch, containerRef.current);
    return () => { p5InstanceRef.current?.remove(); };
  }, []); 

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none pointer-events-auto" 
      onDragOver={(e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; }}
      onDrop={handleDrop}
    />
  );
});

export default LogicCanvas;

import React, { useState, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas, { LogicCanvasHandle } from './components/LogicCanvas';
import BitViewer from './components/BitViewer';
import { ComponentType, CircuitComponent, FunctionCircuit, PortSide } from './types';
import { COMPONENT_DEFINITIONS } from './constants';
import { useProjectManager } from './hooks/useProjectManager';

const App: React.FC = () => {
  // -- UI State --
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(false);

  // Speed Control State
  const [speedSlider, setSpeedSlider] = useState(90); 
  const tickSpeed = speedSlider === 100 ? 0 : Math.max(1, 500 - (speedSlider * 5));

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newFuncName, setNewFuncName] = useState("");
  const [isProjectMenuOpen, setIsProjectMenuOpen] = useState(false);

  // -- Component Selection State --
  const [selectedComponent, setSelectedComponent] = useState<CircuitComponent | null>(null);
  const [tempLabel, setTempLabel] = useState("");

  // -- New: Bit Width Selection --
  const [selectedBitWidth, setSelectedBitWidth] = useState<number>(1);

  // -- Drag State --
  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [draggedFuncId, setDraggedFuncId] = useState<string | undefined>(undefined);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number, functionId?: string, bitWidth: number} | null>(null);

  // -- References --
  const canvasWrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<LogicCanvasHandle>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // -- Project Data Management --
  const {
      functions,
      activeFunctionId,
      activeFunction,
      lastSaved,
      dataVersion,
      switchToFunction,
      addFunction,
      deleteFunction,
      importData,
      clearData,
      persist
  } = useProjectManager(canvasRef);

  // -- Interactions --

  const handleTouchStartItem = (type: ComponentType, pos: {x: number, y: number}, functionId?: string) => {
    setDraggedType(type);
    setDraggedFuncId(functionId);
    setDragPos(pos);
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); 
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedType && dragPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left && dragPos.x <= rect.right &&
          dragPos.y >= rect.top && dragPos.y <= rect.bottom
        ) {
          setPendingDrop({ type: draggedType, x: dragPos.x - rect.left, y: dragPos.y - rect.top, functionId: draggedFuncId, bitWidth: selectedBitWidth });
        }
      }
      setDraggedType(null);
      setDraggedFuncId(undefined);
      setDragPos(null);
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }
    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, draggedFuncId, selectedBitWidth]); // Optimized deps

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const parsed = JSON.parse(e.target?.result as string);
            if (Array.isArray(parsed)) {
                if (confirm("Replace current project?")) {
                    importData(parsed, true);
                    setSelectedComponent(null);
                    setIsPlaying(false);
                }
            } else if (parsed.id) {
                importData(parsed, false);
                alert(`Imported: ${parsed.name}`);
            }
        } catch (err) { alert("Invalid File"); }
        if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsText(file);
  };

  const handleExport = (type: 'PROJECT' | 'FUNCTION') => {
      const data = type === 'PROJECT' 
        ? functions.map(f => f.id === activeFunctionId && canvasRef.current ? {...f, ...canvasRef.current.getData()} : f)
        : (canvasRef.current ? {...activeFunction, ...canvasRef.current.getData()} : activeFunction);

      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = type === 'PROJECT' ? `project.json` : `${activeFunction.name.replace(/\s+/g, '_')}.json`;
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      setIsProjectMenuOpen(false);
  };

  const createFunction = (e: React.FormEvent) => {
      e.preventDefault();
      if (newFuncName.trim()) {
          addFunction(newFuncName);
          setNewFuncName("");
          setIsModalOpen(false);
      }
  };

  const handleSelectionChange = (comp: CircuitComponent | null) => {
      setSelectedComponent(comp);
      if (comp) setTempLabel(comp.customLabel || "");
      else setTempLabel("");
  };

  const updateProp = (updates: Partial<CircuitComponent>) => {
    if (selectedComponent && canvasRef.current) {
        canvasRef.current.updateSelectedComponent(updates);
        setSelectedComponent(prev => prev ? { ...prev, ...updates } : null);
    }
  };

  // Track the ID in a ref to decouple the polling effect from selectedComponent state updates
  const selectedIdRef = useRef<string | null>(null);
  useEffect(() => { selectedIdRef.current = selectedComponent?.id || null; }, [selectedComponent]);

  // -- Live Monitor for Selected Component --
  useEffect(() => {
      if (!isPlaying) return;

      const interval = setInterval(() => {
          const currentId = selectedIdRef.current;
          if (!currentId || !canvasRef.current) return;

          const { components } = canvasRef.current.getData();
          const freshComp = components.find(c => c.id === currentId);

          if (freshComp) {
              setSelectedComponent(prev => {
                  // Guard against stale updates if selection changed
                  if (!prev || prev.id !== currentId) return prev;

                  // Deep compare key data values to avoid unnecessary re-renders
                  const prevHash = JSON.stringify({ i: prev.inputValues, o: prev.outputValues });
                  const newHash = JSON.stringify({ i: freshComp.inputValues, o: freshComp.outputValues });

                  if (prevHash !== newHash) {
                      return { ...freshComp };
                  }
                  // Return exact same object reference to prevent re-render
                  return prev;
              });
          }
      }, 100);

      return () => clearInterval(interval);
  }, [isPlaying]); 

  const handleBitToggle = (index: number) => {
      if (!selectedComponent || !canvasRef.current) return;

      const currentBus = selectedComponent.outputValues[0] || [];
      const newVal = !currentBus[index];

      canvasRef.current.setComponentOutputBit(selectedComponent.id, index, newVal);

      // Update local state immediately for responsiveness
      const newBus = [...currentBus];
      while(newBus.length <= index) newBus.push(false);
      newBus[index] = newVal;

      setSelectedComponent({ 
          ...selectedComponent, 
          outputValues: [newBus]
      });
  };

  const handleBatchBusChange = (newBus: boolean[]) => {
      if (!selectedComponent || !canvasRef.current) return;

      canvasRef.current.updateSelectedComponent({ outputValues: [newBus] });
      setSelectedComponent({ ...selectedComponent, outputValues: [newBus] });
  };

  return (
    <div className="fixed inset-0 flex bg-slate-50 text-slate-800 font-sans overflow-hidden select-none overscroll-none">
      <input type="file" ref={fileInputRef} onChange={handleFileImport} accept=".json" className="hidden" />

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={setSelectedTool}
        selectedBitWidth={selectedBitWidth}
        onSelectBitWidth={setSelectedBitWidth}
        onTouchStartItem={handleTouchStartItem}
        functionLibrary={functions}
      />

      <main className="flex-1 flex flex-col relative overflow-hidden">
        {/* HUD */}
        <div className="absolute top-4 left-4 right-4 bg-white/95 backdrop-blur shadow-sm rounded-md flex flex-wrap items-center justify-between px-4 py-2 z-10 border border-slate-200 gap-2 min-h-[50px]">

          <div className="flex items-center space-x-2">
             <div className="flex items-center bg-slate-100 rounded p-1 border border-slate-200">
               <span className="text-xs font-bold text-slate-400 px-2 hidden sm:inline">FUNC:</span>
               <select 
                 value={activeFunctionId}
                 onChange={(e) => { setIsPlaying(false); switchToFunction(e.target.value); }}
                 className="bg-transparent text-sm font-semibold text-slate-700 outline-none w-24 sm:w-32 cursor-pointer py-1"
               >
                 {functions.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
               </select>
               <button onClick={() => setIsModalOpen(true)} className="ml-2 w-8 h-8 bg-blue-100 text-blue-600 rounded hover:bg-blue-200 font-bold">+</button>
               {activeFunctionId !== 'main' && (
                 <button onClick={() => deleteFunction(activeFunctionId)} className="ml-1 w-8 h-8 bg-red-100 text-red-500 rounded hover:bg-red-200 font-bold">×</button>
               )}
             </div>

             <div className="h-5 w-px bg-slate-200 hidden sm:block"></div>

             <button 
               onClick={() => setIsPlaying(!isPlaying)}
               className="px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded text-sm font-semibold text-slate-700 w-24"
             >
               {isPlaying ? 'Pause' : 'Resume'}
             </button>

             {/* Bit Viewer Injection */}
             {selectedComponent && selectedComponent.bitWidth >= 1 && (
                 <div className="hidden md:block pl-2 border-l border-slate-200">
                    <BitViewer 
                      component={selectedComponent} 
                      onToggleBit={handleBitToggle} 
                      onChangeAll={handleBatchBusChange}
                    />
                 </div>
             )}

          </div>

          <div className="flex items-center space-x-3 w-full md:w-auto justify-end">
             {selectedComponent && (
                 <div className="flex items-center space-x-2 flex-1 md:flex-none justify-center">
                     <button 
                         onClick={() => canvasRef.current?.focusComponent(selectedComponent.id)}
                         className="bg-white border border-slate-300 hover:bg-slate-50 text-slate-600 hover:text-slate-800 rounded px-2 py-1 text-xs font-bold shadow-sm transition-colors"
                         title="Center View on Selection"
                     >
                        Focus
                     </button>

                     {/* Port Side Selector for Inputs/Outputs */}
                     {(selectedComponent.type === ComponentType.INPUT_SWITCH || selectedComponent.type === ComponentType.OUTPUT_LED) && (
                       <div className="flex items-center bg-slate-50 px-2 py-1 rounded border border-slate-200">
                           <span className="text-[10px] font-bold text-slate-400 mr-1 uppercase">Side</span>
                           <select 
                               value={selectedComponent.icPortSide || (selectedComponent.type === 'INPUT' ? 'right' : 'left')}
                               onChange={(e) => updateProp({ icPortSide: e.target.value as PortSide })}
                               className="bg-transparent text-xs font-semibold text-slate-700 outline-none cursor-pointer"
                           >
                               <option value="left">Left</option>
                               <option value="right">Right</option>
                               <option value="top">Top</option>
                               <option value="bottom">Bottom</option>
                           </select>
                       </div>
                     )}

                     <div className="flex items-center bg-yellow-50 px-2 py-1 rounded border border-yellow-200">
                        <input 
                            type="text" 
                            value={tempLabel}
                            onChange={(e) => { setTempLabel(e.target.value); updateProp({ customLabel: e.target.value }); }}
                            className="bg-white border border-yellow-200 text-sm px-2 py-1 rounded w-24 focus:outline-none"
                            placeholder="Label"
                        />
                     </div>
                 </div>
             )}

             <div className="relative">
                <button onClick={() => setIsProjectMenuOpen(!isProjectMenuOpen)} className="px-3 py-2 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded text-sm font-semibold text-slate-700">
                    Project ▼
                </button>
                {isProjectMenuOpen && (
                    <div className="absolute top-full left-0 mt-2 w-56 bg-white rounded-lg shadow-xl border border-slate-100 py-2 z-50 flex flex-col">
                        <div className="px-4 py-2 text-xs text-slate-400 border-b mb-1">
                            {lastSaved ? `Saved: ${lastSaved.toLocaleTimeString()}` : 'Unsaved'}
                        </div>
                        <button onClick={() => { persist(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm hover:bg-slate-50">💾 Save Now</button>
                        <button onClick={() => { fileInputRef.current?.click(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📂 Import...</button>
                        <button onClick={() => handleExport('PROJECT')} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📦 Export All</button>
                        <button onClick={() => handleExport('FUNCTION')} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📄 Export Active</button>
                        <div className="h-px bg-slate-100 my-1"></div>
                        <button onClick={() => { if(confirm("Clear all data?")) clearData(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50">🗑️ Reset</button>
                    </div>
                )}
                {isProjectMenuOpen && <div className="fixed inset-0 z-40" onClick={() => setIsProjectMenuOpen(false)}></div>}
             </div>
          </div>
        </div>

        {/* Canvas */}
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            key={`${activeFunctionId}-${dataVersion}`}
            ref={canvasRef}
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            initialComponents={activeFunction.components}
            initialWires={activeFunction.wires}
            functionLibrary={functions}
            onPendingDropHandled={() => setPendingDrop(null)}
            onSelectionChange={handleSelectionChange}
          />
        </div>

        {/* Drag Ghost */}
        {draggedType && dragPos && (
          <div className="fixed pointer-events-none z-50 opacity-80" style={{ left: dragPos.x, top: dragPos.y, transform: 'translate(-50%, -50%)' }}>
            <div className="w-12 h-12 bg-blue-100 border-2 border-blue-500 rounded flex items-center justify-center shadow-xl">
              <span className="text-[10px] font-bold text-blue-800">{draggedType === 'IC' ? 'IC' : COMPONENT_DEFINITIONS[draggedType].label}</span>
              <span className="absolute bottom-0 right-0 bg-blue-600 text-white text-[9px] px-1 rounded-tl">{selectedBitWidth}</span>
            </div>
          </div>
        )}

        {/* Modal */}
        {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden">
              <div className="bg-slate-50 px-4 py-3 border-b border-slate-100"><h3 className="font-bold">New Function</h3></div>
              <form onSubmit={createFunction} className="p-4">
                <input autoFocus type="text" value={newFuncName} onChange={(e) => setNewFuncName(e.target.value)} placeholder="Function Name" className="w-full px-3 py-2 border rounded-lg mb-4" />
                <div className="flex justify-end space-x-2">
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm font-bold text-slate-500">Cancel</button>
                  <button type="submit" className="px-4 py-2 text-sm font-bold text-white bg-blue-600 rounded-lg">Create</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import p5Types from 'p5'; 
import { ComponentType, CircuitComponent, Wire, Point, FunctionCircuit } from '../types';
import { GRID_SIZE, COLOR_BG } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';
import { CircuitRenderer } from '../logic/circuitRenderer';

declare global {
  interface Window { p5: any; }
}

export interface LogicCanvasHandle {
  getData: () => { components: CircuitComponent[], wires: Wire[] };
  updateSelectedComponent: (updates: Partial<CircuitComponent>) => void;
  deleteSelected: () => void;
  setComponentOutputBit: (compId: string, bitIndex: number, value: boolean) => void;
  focusComponent: (compId: string) => void;
}

interface LogicCanvasProps {
  tool: 'SELECT' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number; 
  pendingDrop?: { type: ComponentType, x: number, y: number, functionId?: string, bitWidth?: number } | null;
  initialComponents: CircuitComponent[];
  initialWires: Wire[];
  functionLibrary: FunctionCircuit[];
  onPendingDropHandled?: () => void;
  onSelectionChange?: (component: CircuitComponent | null) => void;
}

interface ViewportState {
  x: number;
  y: number;
  zoom: number;
}

const LogicCanvas = forwardRef<LogicCanvasHandle, LogicCanvasProps>(({ 
  tool, 
  isPlaying, 
  tickSpeedMs, 
  pendingDrop, 
  initialComponents,
  initialWires,
  functionLibrary,
  onPendingDropHandled,
  onSelectionChange
}, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  const componentsRef = useRef<CircuitComponent[]>(JSON.parse(JSON.stringify(initialComponents)));
  const wiresRef = useRef<Wire[]>(JSON.parse(JSON.stringify(initialWires)));

  const selectedCompId = useRef<string | null>(null);
  const activeDragId = useRef<string | null>(null);

  const viewportRef = useRef<ViewportState>({ x: 0, y: 0, zoom: 1.0 });
  const isPanningRef = useRef<boolean>(false);
  const isDraggingComp = useRef<boolean>(false);
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output', bitWidth: number } | null>(null);
  const dragOffset = useRef<Point>({ x: 0, y: 0 }); 
  const accumulatorRef = useRef<number>(0);

  const tickSpeedRef = useRef(tickSpeedMs);
  const isPlayingRef = useRef(isPlaying);
  const toolRef = useRef(tool);
  const libraryRef = useRef(functionLibrary);

  useEffect(() => { tickSpeedRef.current = tickSpeedMs; }, [tickSpeedMs]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { toolRef.current = tool; }, [tool]);
  useEffect(() => { libraryRef.current = functionLibrary; }, [functionLibrary]);

  useImperativeHandle(ref, () => ({
    getData: () => ({
        components: componentsRef.current,
        wires: wiresRef.current
    }),
    updateSelectedComponent: (updates: Partial<CircuitComponent>) => {
        if (selectedCompId.current) {
            const comp = componentsRef.current.find(c => c.id === selectedCompId.current);
            if (comp) Object.assign(comp, updates);
        }
    },
    deleteSelected: () => {
        if (selectedCompId.current) {
             const id = selectedCompId.current;
             componentsRef.current = componentsRef.current.filter(c => c.id !== id);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== id && w.toCompId !== id);
             selectedCompId.current = null;
             activeDragId.current = null;
             if(onSelectionChange) onSelectionChange(null);
        }
    },
    setComponentOutputBit: (compId: string, bitIndex: number, value: boolean) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && comp.type === ComponentType.INPUT_SWITCH) {
            const currentBus = comp.outputValues[0] || new Array(comp.bitWidth).fill(false);
            if (currentBus.length !== comp.bitWidth) {
                while(currentBus.length < comp.bitWidth) currentBus.push(false);
            }
            const newBus = [...currentBus];
            newBus[bitIndex] = value;
            comp.outputValues[0] = newBus;
        }
    },
    focusComponent: (compId: string) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && containerRef.current) {
             const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
             const w = dims.w * GRID_SIZE;
             const h = dims.h * GRID_SIZE;

             // Center in World
             const cx = comp.x + w/2;
             const cy = comp.y + h/2;

             // Center in Screen
             const sw = containerRef.current.clientWidth;
             const sh = containerRef.current.clientHeight;

             viewportRef.current.x = (sw/2) - (cx * viewportRef.current.zoom);
             viewportRef.current.y = (sh/2) - (cy * viewportRef.current.zoom);
        }
    }
  }));

  const screenToWorld = (sx: number, sy: number): Point => {
    return {
      x: (sx - viewportRef.current.x) / viewportRef.current.zoom,
      y: (sy - viewportRef.current.y) / viewportRef.current.zoom
    };
  };

  const addComponent = (type: ComponentType, screenX: number, screenY: number, functionId?: string, bitWidth: number = 1) => {
    const worldPos = screenToWorld(screenX, screenY);
    const snapX = Math.round(worldPos.x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(worldPos.y / GRID_SIZE) * GRID_SIZE;

    let inputsCount = 0, outputsCount = 0, label = "", internalState = undefined;
    const def = CircuitRenderer.getComponentDimensions({ type, functionId } as any, libraryRef.current);
    inputsCount = def.inputs;
    outputsCount = def.outputs;

    if (type === ComponentType.CUSTOM_IC && functionId) {
        const func = libraryRef.current.find(f => f.id === functionId);
        if (func) {
            label = func.name;
            internalState = {
                components: JSON.parse(JSON.stringify(func.components)),
                wires: JSON.parse(JSON.stringify(func.wires))
            };
        }
    }

    const newComp: CircuitComponent = {
      id: crypto.randomUUID(),
      type: type,
      x: snapX,
      y: snapY,
      inputValues: new Array(inputsCount).fill([]), 
      outputValues: new Array(outputsCount).fill([]), 
      functionId: functionId,
      internalState: internalState,
      customLabel: type === ComponentType.CUSTOM_IC ? label : undefined,
      bitWidth: bitWidth
    };

    componentsRef.current.push(newComp);
    selectedCompId.current = newComp.id;
    if (onSelectionChange) onSelectionChange(newComp);
  };

  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y, pendingDrop.functionId, pendingDrop.bitWidth);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop]);

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    try {
        const data = e.dataTransfer.getData('application/react-logic-sim');
        if (data && containerRef.current) {
            const parsed = JSON.parse(data);
            const rect = containerRef.current.getBoundingClientRect();
            addComponent(parsed.type, e.clientX - rect.left, e.clientY - rect.top, parsed.functionId, parsed.bitWidth);
        }
    } catch(err) { console.error("Drop failed", err); }
  };

  // Helper to determine port width
  const getPortWidth = (comp: CircuitComponent, index: number, type: 'input'|'output'): number => {
      // Splitter Logic
      if (comp.type === ComponentType.SPLITTER) {
          if (type === 'input') return comp.bitWidth; // Input = Full Width
          return comp.bitWidth / 2; // Outputs = Half Width
      }
      // Merger Logic
      if (comp.type === ComponentType.MERGER) {
          if (type === 'output') return comp.bitWidth; // Output = Full Width
          return comp.bitWidth / 2; // Inputs = Half Width
      }
      return comp.bitWidth;
  };

  useEffect(() => {
    if (!containerRef.current || !(window as any).p5) return;
    if (p5InstanceRef.current) p5InstanceRef.current.remove();

    const sketch = (p: p5Types) => {
      let pinchDistStart = 0;
      let lastTouchX = 0; let lastTouchY = 0; let isCanvasInteraction = false;

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        document.oncontextmenu = () => false; 
      };

      (p as any).windowResized = () => { if(containerRef.current) p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight); };

      p.draw = () => {
        p.background(COLOR_BG);

        if (isPlayingRef.current) {
          const speed = tickSpeedRef.current;
          if (speed <= 0) {
              for(let i=0; i<10; i++) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components;
                wiresRef.current = result.wires;
              }
              accumulatorRef.current = 0;
          } else {
              accumulatorRef.current += p.deltaTime;
              if (accumulatorRef.current > 500) accumulatorRef.current = 500;
              while (accumulatorRef.current >= speed) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components;
                wiresRef.current = result.wires;
                accumulatorRef.current -= speed;
              }
          }
        } else accumulatorRef.current = 0;

        p.push();
        p.translate(viewportRef.current.x, viewportRef.current.y);
        p.scale(viewportRef.current.zoom);

        CircuitRenderer.drawGrid(p, viewportRef.current);
        wiresRef.current.forEach(w => CircuitRenderer.drawWire(p, w, componentsRef.current, libraryRef.current));

        if (wiringStart.current) {
             const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
             CircuitRenderer.drawDraftWire(p, wiringStart.current, mouseWorld, componentsRef.current, libraryRef.current);
        }

        componentsRef.current.forEach(comp => {
          CircuitRenderer.drawComponent(p, comp, libraryRef.current, comp.id === selectedCompId.current);
        });

        // Hover Highlighting
        if (!activeDragId.current) {
            const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
            const hPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
            if (hPort) {
                const comp = componentsRef.current.find(c => c.id === hPort.compId);
                if (comp) {
                    const pos = CircuitRenderer.getPortPosition(comp, hPort.portIndex, hPort.type, libraryRef.current);
                    p.noFill();

                    // Logic to check validity if wiring
                    let isValid = true;
                    if (wiringStart.current) {
                        if (wiringStart.current.compId === comp.id) isValid = false; // Self
                        else if (wiringStart.current.type === hPort.type) isValid = false; // Input-Input
                        else if (wiringStart.current.bitWidth !== getPortWidth(comp, hPort.portIndex, hPort.type)) isValid = false; // Width Mismatch
                    }

                    p.stroke(isValid ? '#3b82f6' : '#ef4444'); 
                    p.strokeWeight(2);
                    p.circle(pos.x, pos.y, 14);

                    if (wiringStart.current && !isValid) {
                        p.noStroke(); p.fill('#ef4444'); p.textSize(10);
                        if (wiringStart.current.bitWidth !== getPortWidth(comp, hPort.portIndex, hPort.type)) {
                            p.text(`Width: ${getPortWidth(comp, hPort.portIndex, hPort.type)} vs ${wiringStart.current.bitWidth}`, pos.x, pos.y - 15);
                        }
                    }
                }
            }
        }

        p.pop();
      };

      const getHoveredPort = (wx: number, wy: number) => {
        const HIT_RADIUS = 12;
        for (const comp of componentsRef.current) {
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          for (let i = 0; i < dims.inputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'input', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'input' as const };
          }
          for (let i = 0; i < dims.outputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'output', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'output' as const };
          }
        }
        return null;
      };

      const getHoveredComponent = (wx: number, wy: number) => {
        for (const comp of componentsRef.current) {
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          if (wx > comp.x && wx < comp.x + (dims.w * GRID_SIZE) &&
              wy > comp.y && wy < comp.y + (dims.h * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // -- Interactions --
      (p as any).touchStarted = (e: any) => { if (e.target !== (p as any).canvas) { isCanvasInteraction = false; return true; } isCanvasInteraction = true; if (p.touches.length === 2) { const t0 = p.touches[0] as any, t1 = p.touches[1] as any; pinchDistStart = p.dist(t0.x, t0.y, t1.x, t1.y); } else if (p.touches.length === 1) { const t0 = p.touches[0] as any; lastTouchX = t0.x; lastTouchY = t0.y; p.mousePressed(undefined); } return false; };
      (p as any).touchMoved = (e: any) => { if (!isCanvasInteraction) return true; if (p.touches.length === 2) { const t0 = p.touches[0] as any, t1 = p.touches[1] as any; const currentDist = p.dist(t0.x, t0.y, t1.x, t1.y); if (pinchDistStart > 0) { const scaleFactor = currentDist / pinchDistStart; const newZoom = Math.min(Math.max(viewportRef.current.zoom * scaleFactor, 0.1), 5.0); const cx = (t0.x + t1.x) / 2, cy = (t0.y + t1.y) / 2; const wx = (cx - viewportRef.current.x) / viewportRef.current.zoom; const wy = (cy - viewportRef.current.y) / viewportRef.current.zoom; viewportRef.current.x = cx - wx * newZoom; viewportRef.current.y = cy - wy * newZoom; viewportRef.current.zoom = newZoom; pinchDistStart = currentDist; } } else if (p.touches.length === 1) { const t0 = p.touches[0] as any; if (activeDragId.current) { isDraggingComp.current = true; const mouseWorld = screenToWorld(t0.x, t0.y); const comp = componentsRef.current.find(c => c.id === activeDragId.current); if (comp) { comp.x = Math.round((mouseWorld.x - dragOffset.current.x) / GRID_SIZE) * GRID_SIZE; comp.y = Math.round((mouseWorld.y - dragOffset.current.y) / GRID_SIZE) * GRID_SIZE; } } else if (isPanningRef.current) { viewportRef.current.x += (t0.x - lastTouchX); viewportRef.current.y += (t0.y - lastTouchY); } lastTouchX = t0.x; lastTouchY = t0.y; } return false; };
      (p as any).touchEnded = () => { if (!isCanvasInteraction) return true; if (p.touches.length === 0) p.mouseReleased(); return false; };

      (p as any).mouseWheel = (e: any) => { 
        if (e.target !== (p as any).canvas) {
            return true; 
        }

        const zoomFactor = Math.exp(-e.delta * 0.001); 
        const newZoom = Math.min(Math.max(viewportRef.current.zoom * zoomFactor, 0.1), 5.0); 
        const wx = (p.mouseX - viewportRef.current.x) / viewportRef.current.zoom; 
        const wy = (p.mouseY - viewportRef.current.y) / viewportRef.current.zoom; 
        viewportRef.current.zoom = newZoom; 
        viewportRef.current.x = p.mouseX - wx * newZoom; 
        viewportRef.current.y = p.mouseY - wy * newZoom; 
        return false; 
      };

      p.mousePressed = (e: any) => {
        if (e && e.target !== (p as any).canvas) return;
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
        isDraggingComp.current = false;
        isPanningRef.current = false;

        const port = getHoveredPort(mouseWorld.x, mouseWorld.y);
        if (port) {
            const comp = componentsRef.current.find(c => c.id === port.compId);
            if (!comp) return;

            if (port.type === 'input') {
                const existingWireIndex = wiresRef.current.findIndex(w => w.toCompId === port.compId && w.toPortIndex === port.portIndex);
                if (existingWireIndex !== -1) {
                    const existingWire = wiresRef.current[existingWireIndex];
                    wiresRef.current.splice(existingWireIndex, 1);
                    wiringStart.current = { compId: existingWire.fromCompId, portIndex: existingWire.fromPortIndex, type: 'output', bitWidth: existingWire.bitWidth };
                    return;
                }
            }
          wiringStart.current = { ...port, bitWidth: getPortWidth(comp, port.portIndex, port.type) };
          return;
        }

        const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
        if (compId) {
          if (toolRef.current === 'DELETE') {
             componentsRef.current = componentsRef.current.filter(c => c.id !== compId);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== compId && w.toCompId !== compId);
             if (selectedCompId.current === compId && onSelectionChange) onSelectionChange(null);
             if (activeDragId.current === compId) activeDragId.current = null;
             return;
          }
          const comp = componentsRef.current.find(c => c.id === compId);
          if (comp) {
             selectedCompId.current = compId;
             activeDragId.current = compId;
             dragOffset.current = { x: mouseWorld.x - comp.x, y: mouseWorld.y - comp.y };
             if (onSelectionChange) onSelectionChange(comp);
          }
          return;
        }

        selectedCompId.current = null;
        activeDragId.current = null;
        if (onSelectionChange) onSelectionChange(null);
        isPanningRef.current = true;
      };

      p.mouseDragged = () => {
        if (p.touches.length > 0) return;
        if (isPanningRef.current) {
          viewportRef.current.x += (p.mouseX - p.pmouseX);
          viewportRef.current.y += (p.mouseY - p.pmouseY);
        } else if (activeDragId.current) {
           isDraggingComp.current = true;
           const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
           const comp = componentsRef.current.find(c => c.id === activeDragId.current);
           if (comp) {
             comp.x = Math.round((mouseWorld.x - dragOffset.current.x) / GRID_SIZE) * GRID_SIZE;
             comp.y = Math.round((mouseWorld.y - dragOffset.current.y) / GRID_SIZE) * GRID_SIZE;
           }
        }
      };

      p.mouseReleased = () => {
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        if (activeDragId.current && !isDraggingComp.current) {
          const comp = componentsRef.current.find(c => c.id === activeDragId.current);
          if (comp && comp.type === ComponentType.INPUT_SWITCH) {
              if (comp.bitWidth === 1) {
                  const currentVal = comp.outputValues[0] || [];
                  const width = comp.bitWidth;
                  const isAnyOn = currentVal.some(b => b);
                  comp.outputValues[0] = new Array(width).fill(!isAnyOn);
              }
          }
        }

        activeDragId.current = null;
        isDraggingComp.current = false;
        isPanningRef.current = false;

        if (wiringStart.current) {
          const endPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
             const endComp = componentsRef.current.find(c => c.id === endPort.compId);
             const endWidth = endComp ? getPortWidth(endComp, endPort.portIndex, endPort.type) : 0;

             if (endWidth === wiringStart.current.bitWidth) {
                let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
                let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;

                if (src.type === 'output' && dst.type === 'input') {
                  const exists = wiresRef.current.some(w => w.toCompId === dst.compId && w.toPortIndex === dst.portIndex);
                  if (!exists) {
                    wiresRef.current.push({
                      id: crypto.randomUUID(),
                      fromCompId: src.compId,
                      fromPortIndex: src.portIndex,
                      toCompId: dst.compId,
                      toPortIndex: dst.portIndex,
                      state: new Array(wiringStart.current.bitWidth).fill(false),
                      bitWidth: wiringStart.current.bitWidth
                    });
                  }
                }
             }
          }
          wiringStart.current = null;
        }
      };
    };

    p5InstanceRef.current = new (window as any).p5(sketch, containerRef.current);
    return () => { p5InstanceRef.current?.remove(); };
  }, []); 

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none pointer-events-auto" 
      onDragOver={(e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; }}
      onDrop={handleDrop}
    />
  );
});

export default LogicCanvas;

import React, { useState, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas, { LogicCanvasHandle } from './components/LogicCanvas';
import BitViewer from './components/BitViewer';
import { ComponentType, CircuitComponent, FunctionCircuit, PortSide } from './types';
import { COMPONENT_DEFINITIONS } from './constants';
import { useProjectManager } from './hooks/useProjectManager';

const App: React.FC = () => {
  // -- UI State --
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(false);

  // Speed Control State
  const [speedSlider, setSpeedSlider] = useState(90); 
  const tickSpeed = speedSlider === 100 ? 0 : Math.max(1, 500 - (speedSlider * 5));

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newFuncName, setNewFuncName] = useState("");
  const [isProjectMenuOpen, setIsProjectMenuOpen] = useState(false);

  // -- Component Selection State --
  const [selectedComponent, setSelectedComponent] = useState<CircuitComponent | null>(null);
  const [tempLabel, setTempLabel] = useState("");

  // -- New: Bit Width Selection --
  const [selectedBitWidth, setSelectedBitWidth] = useState<number>(1);

  // -- Drag State --
  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [draggedFuncId, setDraggedFuncId] = useState<string | undefined>(undefined);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number, functionId?: string, bitWidth: number} | null>(null);

  // -- References --
  const canvasWrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<LogicCanvasHandle>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // -- Project Data Management --
  const {
      functions,
      activeFunctionId,
      activeFunction,
      lastSaved,
      dataVersion,
      switchToFunction,
      addFunction,
      deleteFunction,
      importData,
      clearData,
      persist
  } = useProjectManager(canvasRef);

  // -- Interactions --

  const handleTouchStartItem = (type: ComponentType, pos: {x: number, y: number}, functionId?: string) => {
    setDraggedType(type);
    setDraggedFuncId(functionId);
    setDragPos(pos);
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); 
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedType && dragPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left && dragPos.x <= rect.right &&
          dragPos.y >= rect.top && dragPos.y <= rect.bottom
        ) {
          setPendingDrop({ type: draggedType, x: dragPos.x - rect.left, y: dragPos.y - rect.top, functionId: draggedFuncId, bitWidth: selectedBitWidth });
        }
      }
      setDraggedType(null);
      setDraggedFuncId(undefined);
      setDragPos(null);
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }
    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, draggedFuncId, selectedBitWidth]); // Optimized deps

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const parsed = JSON.parse(e.target?.result as string);
            if (Array.isArray(parsed)) {
                if (confirm("Replace current project?")) {
                    importData(parsed, true);
                    setSelectedComponent(null);
                    setIsPlaying(false);
                }
            } else if (parsed.id) {
                importData(parsed, false);
                alert(`Imported: ${parsed.name}`);
            }
        } catch (err) { alert("Invalid File"); }
        if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsText(file);
  };

  const handleExport = (type: 'PROJECT' | 'FUNCTION') => {
      const data = type === 'PROJECT' 
        ? functions.map(f => f.id === activeFunctionId && canvasRef.current ? {...f, ...canvasRef.current.getData()} : f)
        : (canvasRef.current ? {...activeFunction, ...canvasRef.current.getData()} : activeFunction);

      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = type === 'PROJECT' ? `project.json` : `${activeFunction.name.replace(/\s+/g, '_')}.json`;
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      setIsProjectMenuOpen(false);
  };

  const createFunction = (e: React.FormEvent) => {
      e.preventDefault();
      if (newFuncName.trim()) {
          addFunction(newFuncName);
          setNewFuncName("");
          setIsModalOpen(false);
      }
  };

  const handleSelectionChange = (comp: CircuitComponent | null) => {
      setSelectedComponent(comp);
      if (comp) setTempLabel(comp.customLabel || "");
      else setTempLabel("");
  };

  const updateProp = (updates: Partial<CircuitComponent>) => {
    if (selectedComponent && canvasRef.current) {
        canvasRef.current.updateSelectedComponent(updates);
        setSelectedComponent(prev => prev ? { ...prev, ...updates } : null);
    }
  };

  // Track the ID in a ref to decouple the polling effect from selectedComponent state updates
  const selectedIdRef = useRef<string | null>(null);
  useEffect(() => { selectedIdRef.current = selectedComponent?.id || null; }, [selectedComponent]);

  // -- Live Monitor for Selected Component --
  useEffect(() => {
      if (!isPlaying) return;

      const interval = setInterval(() => {
          const currentId = selectedIdRef.current;
          if (!currentId || !canvasRef.current) return;

          const { components } = canvasRef.current.getData();
          const freshComp = components.find(c => c.id === currentId);

          if (freshComp) {
              setSelectedComponent(prev => {
                  // Guard against stale updates if selection changed
                  if (!prev || prev.id !== currentId) return prev;

                  // Deep compare key data values to avoid unnecessary re-renders
                  const prevHash = JSON.stringify({ i: prev.inputValues, o: prev.outputValues });
                  const newHash = JSON.stringify({ i: freshComp.inputValues, o: freshComp.outputValues });

                  if (prevHash !== newHash) {
                      return { ...freshComp };
                  }
                  // Return exact same object reference to prevent re-render
                  return prev;
              });
          }
      }, 100);

      return () => clearInterval(interval);
  }, [isPlaying]); 

  const handleBitToggle = (index: number) => {
      if (!selectedComponent || !canvasRef.current) return;

      const currentBus = selectedComponent.outputValues[0] || [];
      const newVal = !currentBus[index];

      canvasRef.current.setComponentOutputBit(selectedComponent.id, index, newVal);

      // Update local state immediately for responsiveness
      const newBus = [...currentBus];
      while(newBus.length <= index) newBus.push(false);
      newBus[index] = newVal;

      setSelectedComponent({ 
          ...selectedComponent, 
          outputValues: [newBus]
      });
  };

  const handleBatchBusChange = (newBus: boolean[]) => {
      if (!selectedComponent || !canvasRef.current) return;

      canvasRef.current.updateSelectedComponent({ outputValues: [newBus] });
      setSelectedComponent({ ...selectedComponent, outputValues: [newBus] });
  };

  return (
    <div className="fixed inset-0 flex bg-slate-50 text-slate-800 font-sans overflow-hidden select-none overscroll-none">
      <input type="file" ref={fileInputRef} onChange={handleFileImport} accept=".json" className="hidden" />

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={setSelectedTool}
        selectedBitWidth={selectedBitWidth}
        onSelectBitWidth={setSelectedBitWidth}
        onTouchStartItem={handleTouchStartItem}
        functionLibrary={functions}
      />

      <main className="flex-1 flex flex-col relative overflow-hidden">
        {/* HUD */}
        <div className="absolute top-4 left-4 right-4 bg-white/95 backdrop-blur shadow-sm rounded-md flex flex-wrap items-center justify-between px-4 py-2 z-10 border border-slate-200 gap-2 min-h-[50px]">

          <div className="flex items-center space-x-2">
             <div className="flex items-center bg-slate-100 rounded p-1 border border-slate-200">
               <span className="text-xs font-bold text-slate-400 px-2 hidden sm:inline">FUNC:</span>
               <select 
                 value={activeFunctionId}
                 onChange={(e) => { setIsPlaying(false); switchToFunction(e.target.value); }}
                 className="bg-transparent text-sm font-semibold text-slate-700 outline-none w-24 sm:w-32 cursor-pointer py-1"
               >
                 {functions.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
               </select>
               <button onClick={() => setIsModalOpen(true)} className="ml-2 w-8 h-8 bg-blue-100 text-blue-600 rounded hover:bg-blue-200 font-bold">+</button>
               {activeFunctionId !== 'main' && (
                 <button onClick={() => deleteFunction(activeFunctionId)} className="ml-1 w-8 h-8 bg-red-100 text-red-500 rounded hover:bg-red-200 font-bold">×</button>
               )}
             </div>

             <div className="h-5 w-px bg-slate-200 hidden sm:block"></div>

             <button 
               onClick={() => setIsPlaying(!isPlaying)}
               className={`px-4 py-1.5 rounded text-sm font-bold w-24 border ${isPlaying ? 'bg-orange-100 text-orange-600 border-orange-200' : 'bg-green-100 text-green-700 border-green-200'}`}
             >
               {isPlaying ? 'PAUSE' : 'RUN'}
             </button>

             {/* Speed Slider */}
             <div className="flex flex-col justify-center bg-slate-50 px-2 py-1 rounded border border-slate-200 w-24 sm:w-32">
                <div className="flex justify-between w-full mb-1">
                    <span className="text-[9px] font-bold text-slate-400">SPEED</span>
                    <span className="text-[9px] font-mono text-slate-500">{speedSlider}%</span>
                </div>
                <input
                    type="range"
                    min="0"
                    max="100"
                    step="5"
                    value={speedSlider}
                    onChange={(e) => setSpeedSlider(Number(e.target.value))}
                    className="w-full h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-blue-500"
                    title="Simulation Speed"
                />
             </div>

             {/* Bit Viewer Injection */}
             {selectedComponent && selectedComponent.bitWidth >= 1 && (
                 <div className="hidden lg:block pl-2 border-l border-slate-200">
                    <BitViewer 
                      component={selectedComponent} 
                      onToggleBit={handleBitToggle} 
                      onChangeAll={handleBatchBusChange}
                    />
                 </div>
             )}

          </div>

          <div className="flex items-center space-x-3 w-full md:w-auto justify-end mt-2 md:mt-0">
             {selectedComponent && (
                 <div className="flex items-center space-x-2 flex-1 md:flex-none justify-center">
                     <button 
                         onClick={() => canvasRef.current?.focusComponent(selectedComponent.id)}
                         className="bg-white border border-slate-300 hover:bg-slate-50 text-slate-600 hover:text-slate-800 rounded px-2 py-1 text-xs font-bold shadow-sm transition-colors"
                         title="Center View on Selection"
                     >
                        Focus
                     </button>

                     {/* Port Side Selector for Inputs/Outputs */}
                     {(selectedComponent.type === ComponentType.INPUT_SWITCH || selectedComponent.type === ComponentType.OUTPUT_LED) && (
                       <div className="flex items-center bg-slate-50 px-2 py-1 rounded border border-slate-200">
                           <span className="text-[10px] font-bold text-slate-400 mr-1 uppercase">Side</span>
                           <select 
                               value={selectedComponent.icPortSide || (selectedComponent.type === 'INPUT' ? 'right' : 'left')}
                               onChange={(e) => updateProp({ icPortSide: e.target.value as PortSide })}
                               className="bg-transparent text-xs font-semibold text-slate-700 outline-none cursor-pointer"
                           >
                               <option value="left">Left</option>
                               <option value="right">Right</option>
                               <option value="top">Top</option>
                               <option value="bottom">Bottom</option>
                           </select>
                       </div>
                     )}

                     <div className="flex items-center bg-yellow-50 px-2 py-1 rounded border border-yellow-200">
                        <input 
                            type="text" 
                            value={tempLabel}
                            onChange={(e) => { setTempLabel(e.target.value); updateProp({ customLabel: e.target.value }); }}
                            className="bg-white border border-yellow-200 text-sm px-2 py-1 rounded w-24 focus:outline-none"
                            placeholder="Label"
                        />
                     </div>
                 </div>
             )}

             <div className="relative">
                <button onClick={() => setIsProjectMenuOpen(!isProjectMenuOpen)} className="px-3 py-2 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded text-sm font-semibold text-slate-700">
                    Project ▼
                </button>
                {isProjectMenuOpen && (
                    <div className="absolute top-full left-0 mt-2 w-56 bg-white rounded-lg shadow-xl border border-slate-100 py-2 z-50 flex flex-col">
                        <div className="px-4 py-2 text-xs text-slate-400 border-b mb-1">
                            {lastSaved ? `Saved: ${lastSaved.toLocaleTimeString()}` : 'Unsaved'}
                        </div>
                        <button onClick={() => { persist(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm hover:bg-slate-50">💾 Save Now</button>
                        <button onClick={() => { fileInputRef.current?.click(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📂 Import...</button>
                        <button onClick={() => handleExport('PROJECT')} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📦 Export All</button>
                        <button onClick={() => handleExport('FUNCTION')} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📄 Export Active</button>
                        <div className="h-px bg-slate-100 my-1"></div>
                        <button onClick={() => { if(confirm("Clear all data?")) clearData(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50">🗑️ Reset</button>
                    </div>
                )}
                {isProjectMenuOpen && <div className="fixed inset-0 z-40" onClick={() => setIsProjectMenuOpen(false)}></div>}
             </div>
          </div>
        </div>

        {/* Canvas */}
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            key={`${activeFunctionId}-${dataVersion}`}
            ref={canvasRef}
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            initialComponents={activeFunction.components}
            initialWires={activeFunction.wires}
            functionLibrary={functions}
            onPendingDropHandled={() => setPendingDrop(null)}
            onSelectionChange={handleSelectionChange}
          />
        </div>

        {/* Drag Ghost */}
        {draggedType && dragPos && (
          <div className="fixed pointer-events-none z-50 opacity-80" style={{ left: dragPos.x, top: dragPos.y, transform: 'translate(-50%, -50%)' }}>
            <div className="w-12 h-12 bg-blue-100 border-2 border-blue-500 rounded flex items-center justify-center shadow-xl">
              <span className="text-[10px] font-bold text-blue-800">{draggedType === 'IC' ? 'IC' : COMPONENT_DEFINITIONS[draggedType].label}</span>
              <span className="absolute bottom-0 right-0 bg-blue-600 text-white text-[9px] px-1 rounded-tl">{selectedBitWidth}</span>
            </div>
          </div>
        )}

        {/* Modal */}
        {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden">
              <div className="bg-slate-50 px-4 py-3 border-b border-slate-100"><h3 className="font-bold">New Function</h3></div>
              <form onSubmit={createFunction} className="p-4">
                <input autoFocus type="text" value={newFuncName} onChange={(e) => setNewFuncName(e.target.value)} placeholder="Function Name" className="w-full px-3 py-2 border rounded-lg mb-4" />
                <div className="flex justify-end space-x-2">
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm font-bold text-slate-500">Cancel</button>
                  <button type="submit" className="px-4 py-2 text-sm font-bold text-white bg-blue-600 rounded-lg">Create</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import p5Types from 'p5';
import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_GRID, COLOR_WIRE_ON, COLOR_WIRE_OFF, COLOR_BUS_ON, COLOR_BUS_OFF, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE } from '../constants';

type PortPoint = { x: number, y: number, side: 'top' | 'bottom' | 'left' | 'right' };

// Helper: Convert boolean array to Hex String using BigInt to support > 31 bits
export const bitsToHex = (bits: boolean[]): string => {
  if (!bits || bits.length === 0) return "0";
  let val = 0n;
  for (let i = 0; i < bits.length; i++) {
      if (bits[i]) val |= (1n << BigInt(i));
  }
  return val.toString(16).toUpperCase();
};

export class CircuitRenderer {

  static getSide(c: CircuitComponent, isInput: boolean): PortSide {
    // For Custom ICs, we want to respect the user's side selection.
    // Default: Inputs Left, Outputs Right.
    return c.icPortSide || (isInput ? 'left' : 'right');
  }

  // --- Sorting Logic for Pins (Must match CircuitEngine) ---
  static sortICPorts(components: CircuitComponent[], isInput: boolean) {
      const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };

      return [...components].sort((a, b) => {
          const sideA = CircuitRenderer.getSide(a, isInput);
          const sideB = CircuitRenderer.getSide(b, isInput);

          if (sideOrder[sideA] !== sideOrder[sideB]) {
              return sideOrder[sideA] - sideOrder[sideB];
          }
          // Same side sorting
          if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
          return a.y - b.y;
      });
  }

  static getComponentDimensions(comp: CircuitComponent, library: FunctionCircuit[] = []) {
    const def = COMPONENT_DEFINITIONS[comp.type];

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
       const funcDef = library.find(f => f.id === comp.functionId);
       if (funcDef) {
          const inputs = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH);
          const outputs = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

          // Count ports per side
          const countSide = (list: CircuitComponent[], side: PortSide, isInput: boolean) => 
              list.filter(c => CircuitRenderer.getSide(c, isInput) === side).length;

          const topCount = countSide(inputs, 'top', true) + countSide(outputs, 'top', false);
          const bottomCount = countSide(inputs, 'bottom', true) + countSide(outputs, 'bottom', false);
          const leftCount = countSide(inputs, 'left', true) + countSide(outputs, 'left', false);
          const rightCount = countSide(inputs, 'right', true) + countSide(outputs, 'right', false);

          // Calculate Width/Height
          // Rule: Min 1x1. Tighter fit based on port count.
          // If 0 or 1 port on a side, dimension is 1. If 2 ports, dimension is 2, etc.

          const width = Math.max(1, topCount, bottomCount);
          const height = Math.max(1, leftCount, rightCount);

          return { w: width, h: height, inputs: inputs.length, outputs: outputs.length };
       }
       return { w: 1, h: 1, inputs: 0, outputs: 0 };
    }
    return { w: def.width, h: def.height, inputs: def.inputs, outputs: def.outputs };
  }

  static getPortPosition(comp: CircuitComponent, index: number, type: 'input' | 'output', library: FunctionCircuit[] = []): PortPoint {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;

    // 1. Dynamic pin positioning for IO (Inside function editor)
    if (comp.type === ComponentType.INPUT_SWITCH && type === 'output') {
        const side = comp.icPortSide || 'right'; // Default Output of an Switch faces Right
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }
    if (comp.type === ComponentType.OUTPUT_LED && type === 'input') {
        const side = comp.icPortSide || 'left'; // Default Input of an LED faces Left
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }

    // 2. Custom IC (Outside view)
    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
         const funcDef = library.find(f => f.id === comp.functionId);
         if (funcDef) {
             const isInput = type === 'input';
             const unsorted = isInput 
                ? funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH)
                : funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

             // Must use SAME sorting as engine
             const sorted = CircuitRenderer.sortICPorts(unsorted, isInput);
             const targetComp = sorted[index];

             if (targetComp) {
                 const side = CircuitRenderer.getSide(targetComp, isInput);

                 // Find all ports on this specific side to space them evenly
                 const inputsOnSide = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH && CircuitRenderer.getSide(c, true) === side);
                 const outputsOnSide = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED && CircuitRenderer.getSide(c, false) === side);

                 // Merge and sort them to find relative position of THIS port
                 const allOnSide = [...inputsOnSide, ...outputsOnSide];
                 // Sort based on geometric position (x or y)
                 allOnSide.sort((a, b) => {
                    if (side === 'top' || side === 'bottom') return a.x - b.x;
                    return a.y - b.y;
                 });

                 const localIndex = allOnSide.indexOf(targetComp);
                 const count = allOnSide.length;
                 const stepX = w / (count + 1);
                 const stepY = h / (count + 1);

                 if (side === 'top') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y, side: 'top' };
                 if (side === 'bottom') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y + h, side: 'bottom' };
                 if (side === 'left') return { x: comp.x, y: comp.y + ((localIndex + 1) * stepY), side: 'left' };
                 if (side === 'right') return { x: comp.x + w, y: comp.y + ((localIndex + 1) * stepY), side: 'right' };
             }
         }
    }

    // 3. Standard Components
    // Splitter
    if (comp.type === ComponentType.SPLITTER) {
        if (type === 'input') return { x: comp.x, y: comp.y + h/2, side: 'left' };
        const step = h / 3;
        return { x: comp.x + w, y: comp.y + ((index+1)*step), side: 'right' };
    }
    // Merger
    if (comp.type === ComponentType.MERGER) {
        if (type === 'output') return { x: comp.x + w, y: comp.y + h/2, side: 'right' };
        const step = h / 3;
        return { x: comp.x, y: comp.y + ((index+1)*step), side: 'left' };
    }

    // Standard Gates
    const count = type === 'input' ? dims.inputs : dims.outputs;
    const yStep = h / (count + 1);
    return {
      x: type === 'input' ? comp.x : comp.x + w,
      y: comp.y + ((index + 1) * yStep),
      side: type === 'input' ? 'left' : 'right'
    };
  }

  // --- Helpers ---

  static getWireColor(width: number, hasSignal: boolean) {
      if (width === 1) return hasSignal ? COLOR_WIRE_ON : COLOR_WIRE_OFF;
      return hasSignal ? COLOR_BUS_ON : COLOR_BUS_OFF;
  }

  static getWireWeight(width: number) {
      if (width === 1) return 3;
      if (width <= 4) return 4;
      if (width <= 16) return 5;
      if (width <= 64) return 6;
      return 7;
  }

  static isSignalActive(state: boolean[]): boolean {
      if (!state) return false;
      return state.some(b => b === true);
  }

  // --- Drawing ---

  static drawGrid(p: p5Types, viewport: { x: number, y: number, zoom: number }) {
    const visibleL = -viewport.x / viewport.zoom;
    const visibleT = -viewport.y / viewport.zoom;
    const visibleR = (p.width - viewport.x) / viewport.zoom;
    const visibleB = (p.height - viewport.y) / viewport.zoom;

    const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
    const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
    const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
    const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

    p.stroke(COLOR_GRID);
    p.strokeWeight(1 / viewport.zoom); 

    for (let x = startX; x <= endX; x += GRID_SIZE) p.line(x, visibleT, x, visibleB);
    for (let y = startY; y <= endY; y += GRID_SIZE) p.line(visibleL, y, visibleR, y);
  }

  static drawWire(p: p5Types, wire: Wire, components: CircuitComponent[], library: FunctionCircuit[]) {
      const fromComp = components.find(c => c.id === wire.fromCompId);
      const toComp = components.find(c => c.id === wire.toCompId);
      if (fromComp && toComp) {
        const start = CircuitRenderer.getPortPosition(fromComp, wire.fromPortIndex, 'output', library);
        const end = CircuitRenderer.getPortPosition(toComp, wire.toPortIndex, 'input', library);

        const active = CircuitRenderer.isSignalActive(wire.state);

        p.stroke(CircuitRenderer.getWireColor(wire.bitWidth, active));
        p.strokeWeight(CircuitRenderer.getWireWeight(wire.bitWidth));
        p.noFill();

        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        const cp2 = CircuitRenderer.getWireControlPoint(end, cpOffset);

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);

        // Label for Bus
        if (wire.bitWidth > 1) {
             const midX = p.bezierPoint(start.x, cp1.x, cp2.x, end.x, 0.5);
             const midY = p.bezierPoint(start.y, cp1.y, cp2.y, end.y, 0.5);

             p.noStroke();
             p.fill(COLOR_COMPONENT_BG);
             p.circle(midX, midY, 12);

             p.fill(COLOR_COMPONENT_STROKE);
             p.textAlign(p.CENTER, p.CENTER);
             p.textSize(8);
             p.textStyle(p.BOLD);
             p.text(wire.bitWidth, midX, midY);
             p.textStyle(p.NORMAL);
        }
      }
  }

  static drawDraftWire(p: p5Types, startInfo: { compId: string, portIndex: number, type: 'input'|'output' }, mouseWorld: {x:number, y:number}, components: CircuitComponent[], library: FunctionCircuit[]) {
      const comp = components.find(c => c.id === startInfo.compId);
      if (comp) {
        const start = CircuitRenderer.getPortPosition(comp, startInfo.portIndex, startInfo.type, library);
        p.stroke(COLOR_WIRE_OFF);
        p.strokeWeight(2);
        p.noFill();
        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        let cp2 = { x: mouseWorld.x, y: mouseWorld.y };
        if (startInfo.type === 'output') cp2 = { x: mouseWorld.x - cpOffset, y: mouseWorld.y };
        else cp2 = { x: mouseWorld.x + cpOffset, y: mouseWorld.y };

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, mouseWorld.x, mouseWorld.y);
      }
  }

  static getWireControlPoint(pt: PortPoint, offset: number) {
    if (pt.side === 'top') return { x: pt.x, y: pt.y - offset };
    if (pt.side === 'bottom') return { x: pt.x, y: pt.y + offset };
    if (pt.side === 'left') return { x: pt.x - offset, y: pt.y };
    return { x: pt.x + offset, y: pt.y };
  }

  static drawComponent(p: p5Types, comp: CircuitComponent, library: FunctionCircuit[], isSelected: boolean) {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;
    const inputs = dims.inputs;
    const outputs = dims.outputs;

    p.push();
    p.translate(comp.x, comp.y);

    // Main Draw
    if (comp.type === ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawIC(p, comp, w, h, library);
    } else if (comp.type === ComponentType.SPLITTER) {
        CircuitRenderer.drawSplitter(p, comp, w, h);
    } else if (comp.type === ComponentType.MERGER) {
        CircuitRenderer.drawMerger(p, comp, w, h);
    } else if (comp.type === ComponentType.INPUT_SWITCH) {
        CircuitRenderer.drawSwitch(p, comp, w, h);
    } else if (comp.type === ComponentType.OUTPUT_LED) {
        CircuitRenderer.drawLED(p, comp, w, h);
    } else if (comp.type === ComponentType.HEX_DISPLAY) {
        CircuitRenderer.drawHex(p, comp, w, h);
    } else {
        CircuitRenderer.drawGate(p, comp, w, h);
    }

    // Label (Only if not Custom IC, as IC draws its own label)
    if (comp.type !== ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawLabels(p, comp, w, h);
    }

    // Ports for Standard Components
    if (!['IC','INPUT','OUTPUT','HEX','SPLIT','MERGE'].includes(comp.type)) {
        p.noStroke(); p.fill('#64748b');
        for (let i = 0; i < inputs; i++) p.circle(0, ((i+1) * (h/(inputs+1))), 4);
        for (let i = 0; i < outputs; i++) p.circle(w, ((i+1) * (h/(outputs+1))), 4);
    }

    // Selection Halo
    if (isSelected) {
        p.noFill(); p.stroke('#3b82f6'); p.strokeWeight(2);
        p.rect(-4, -4, w + 8, h + 8, 4);

        // BitWidth info in corner for selected
        p.noStroke(); p.fill('#3b82f6');
        p.textSize(10); p.textAlign(p.RIGHT, p.TOP);
        p.text(`w:${comp.bitWidth}`, w + 4, h + 6);
    } else if (comp.bitWidth > 1) {
        // Always show small bitwidth indicator for buses
        p.noStroke(); p.fill('#94a3b8');
        p.textSize(9); p.textAlign(p.RIGHT, p.BOTTOM);
        p.text(comp.bitWidth, w - 2, h - 2);
    }

    p.pop();
  }

  // --- Helper: Draw Fitted Text with Ellipsis ---
  private static drawFittedText(p: p5Types, text: string, x: number, y: number, maxW: number, maxH: number) {
      let fontSize = 12; // Start larger
      const minFontSize = 8;
      p.textSize(fontSize);
      p.textAlign(p.CENTER, p.CENTER);

      let currentText = text;
      let w = p.textWidth(currentText);

      // If text fits, draw it
      if (w <= maxW) {
          p.text(currentText, x, y);
          return;
      }

      // Try shrinking font size first
      while (fontSize > minFontSize && w > maxW) {
          fontSize--;
          p.textSize(fontSize);
          w = p.textWidth(currentText);
      }

      // If still doesn't fit, truncate with ellipsis
      if (w > maxW) {
          while (currentText.length > 0 && p.textWidth(currentText + '..') > maxW) {
              currentText = currentText.slice(0, -1);
          }
          currentText += '..';
      }

      p.text(currentText, x, y);
  }

  // --- Sub-Renderers ---

  private static drawSplitter(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      // Trapezoid opening to right
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.beginShape();
      p.vertex(0, h * 0.3);
      p.vertex(w, 0);
      p.vertex(w, h);
      p.vertex(0, h * 0.7);
      p.endShape(p.CLOSE);

      // Ports
      p.fill('#64748b'); p.noStroke();
      p.circle(0, h/2, 5); // In
      const step = h/3;
      p.circle(w, step, 4); // Out 1
      p.circle(w, step*2, 4); // Out 2

      // Internal Text
      p.fill('#0f172a'); p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
      p.text("/", w/2, h/2);
  }

  private static drawMerger(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      // Trapezoid closing to right
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.beginShape();
      p.vertex(0, 0);
      p.vertex(w, h * 0.3);
      p.vertex(w, h * 0.7);
      p.vertex(0, h);
      p.endShape(p.CLOSE);

      // Ports
      p.fill('#64748b'); p.noStroke();
      const step = h/3;
      p.circle(0, step, 4); 
      p.circle(0, step*2, 4);
      p.circle(w, h/2, 5);

      p.fill('#0f172a'); p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
      p.text("&", w/2, h/2);
  }

  private static drawIC(p: p5Types, comp: CircuitComponent, w: number, h: number, library: FunctionCircuit[]) {
    // Body - slight blue tint
    p.fill('#eff6ff'); 
    p.stroke('#3b82f6'); // Blue border
    p.strokeWeight(2);
    p.rect(0, 0, w, h, 6);

    // Label
    p.fill('#1e3a8a'); 
    p.noStroke(); 
    p.textStyle(p.BOLD);

    // Draw Name - Allow tight fit
    const label = comp.customLabel || "IC";
    CircuitRenderer.drawFittedText(p, label, w/2, h/2, w - 4, h - 4);

    // Draw Ports
    if (comp.functionId) {
        const funcDef = library.find(f => f.id === comp.functionId);
        if (funcDef) {
            const inputs = CircuitRenderer.sortICPorts(funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH), true);
            const outputs = CircuitRenderer.sortICPorts(funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED), false);

            const drawPort = (c: CircuitComponent, index: number, isInput: boolean) => {
                const pt = CircuitRenderer.getPortPosition(comp, index, isInput ? 'input' : 'output', library);
                // Convert absolute to relative for drawing inside component loop
                const rx = pt.x - comp.x;
                const ry = pt.y - comp.y;

                // Draw Port Circle
                p.fill(isInput ? '#3b82f6' : '#f59e0b');
                p.stroke('#1e293b'); p.strokeWeight(1);
                p.circle(rx, ry, 6);

                // Draw Internal Label (if exists)
                if (c.customLabel) {
                    p.noStroke();
                    p.fill('#334155');
                    p.textSize(8);
                    p.textStyle(p.NORMAL);

                    if (pt.side === 'left') {
                        p.textAlign(p.LEFT, p.CENTER);
                        p.text(c.customLabel, rx + 6, ry);
                    } else if (pt.side === 'right') {
                        p.textAlign(p.RIGHT, p.CENTER);
                        p.text(c.customLabel, rx - 6, ry);
                    } else if (pt.side === 'top') {
                         p.textAlign(p.CENTER, p.TOP);
                         p.text(c.customLabel, rx, ry + 6);
                    } else { // bottom
                         p.textAlign(p.CENTER, p.BOTTOM);
                         p.text(c.customLabel, rx, ry - 6);
                    }
                }
            };

            inputs.forEach((c, i) => drawPort(c, i, true));
            outputs.forEach((c, i) => drawPort(c, i, false));
        }
    }
  }

  private static drawSwitch(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.outputValues[0]);
      const side = comp.icPortSide || 'right';
      const boxSize = GRID_SIZE * 0.6;
      const boxOffset = (GRID_SIZE - boxSize) / 2;

      let portX = w, portY = h/2;
      if (side === 'left') { portX = 0; }
      else if (side === 'top') { portX = w/2; portY = 0; }
      else if (side === 'bottom') { portX = w/2; portY = h; }

      p.stroke(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_STROKE);
      p.strokeWeight(2);
      p.line(w/2, h/2, portX, portY);
      p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

      p.stroke(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_STROKE);
      p.fill(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_BG);
      p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);

      p.noStroke(); p.fill(isOn ? '#fff' : '#475569');

      // If bitWidth >= 16, do NOT show the value (too small). Show "16b" etc.
      if (comp.bitWidth >= 16) {
          p.textSize(9); p.textAlign(p.CENTER, p.CENTER);
          p.text(`${comp.bitWidth}b`, w/2, h/2);
      } else if (comp.bitWidth > 1) {
          // Show Hex if < 16 bits
          const hex = "0x" + bitsToHex(comp.outputValues[0] || []);
          CircuitRenderer.drawFittedText(p, hex, w/2, h/2, boxSize - 2, boxSize - 2);
      } else {
          p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
          p.text(isOn ? "1" : "0", w/2, h/2);
      }

      // Indicate direction with a small arrow/triangle if needed, or just rely on pin pos.
  }

  private static drawLED(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.inputValues[0]);
      const side = comp.icPortSide || 'left';
      const boxSize = GRID_SIZE * 0.6;
      const boxOffset = (GRID_SIZE - boxSize) / 2;

      let portX = 0, portY = h/2;
      if (side === 'right') { portX = w; }
      else if (side === 'top') { portX = w/2; portY = 0; }
      else if (side === 'bottom') { portX = w/2; portY = h; }

      p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.line(w/2, h/2, portX, portY);
      p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

      if (isOn) { p.noStroke(); p.fill(245, 158, 11, 80); p.rect(boxOffset-3, boxOffset-3, boxSize+6, boxSize+6, 6); }
      p.stroke(isOn ? COLOR_BUS_ON : '#334155');
      p.fill(isOn ? COLOR_BUS_ON : '#1e293b');
      p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);

      // Display Value or Width
      p.noStroke(); p.fill(isOn ? '#fff' : '#475569');
      if (comp.bitWidth >= 16) {
           p.textSize(9); p.textAlign(p.CENTER, p.CENTER);
           p.text(`${comp.bitWidth}b`, w/2, h/2);
      } else if (comp.bitWidth > 1) {
           const hex = "0x" + bitsToHex(comp.inputValues[0] || []);
           CircuitRenderer.drawFittedText(p, hex, w/2, h/2, boxSize - 2, boxSize - 2);
      }
  }

  private static drawHex(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const padX = 4;
      p.fill('#0f172a'); p.stroke('#334155'); p.rect(padX, 4, w - (padX*2), h-8, 4);
      p.noStroke(); p.fill('#ef4444'); 

      const hex = bitsToHex(comp.inputValues[0] || []);

      // Draw Fitted Text for Hex Display
      // Available width is (w - padX*2 - 4)
      CircuitRenderer.drawFittedText(p, hex, w/2, h/2, w - (padX*2) - 4, h - 12);

      // Port
      p.fill('#64748b'); p.circle(0, h/2, 5);
  }

  private static drawGate(p: p5Types, comp: CircuitComponent, w: number, h: number) {
    const py = 6;
    const gateW = w - 10;
    const isNegated = ['NAND', 'NOR', 'NOT'].includes(comp.type);
    const bubbleR = 4;
    let bodyW = isNegated ? gateW - (bubbleR*2) : gateW;

    p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
    p.line(gateW, h/2, w, h/2); // Out line

    if (comp.type === 'NOT') {
        p.fill(COLOR_COMPONENT_BG);
        (p as any).triangle(0, py, 0, h - py, bodyW, h / 2);
    } else {
        const isXor = comp.type === 'XOR';
        const isOrFamily = ['OR', 'NOR', 'XOR'].includes(comp.type);
        let startX = 0;

        if (isXor) {
            startX = 5;
            p.noFill();
            p.beginShape(); p.vertex(0, py); (p as any).bezierVertex(3, h * 0.33, 3, h * 0.66, 0, h - py); p.endShape();
        }

        p.fill(COLOR_COMPONENT_BG);
        p.beginShape();
        if (isOrFamily) {
            p.vertex(startX, py); p.vertex(bodyW * 0.5, py);
            (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);
            p.vertex(startX, h - py);
            (p as any).bezierVertex(startX + 5, h * 0.75, startX + 5, h * 0.25, startX, py);
        } else {
            p.vertex(0, py); p.vertex(bodyW * 0.5, py);
            (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);
            p.vertex(0, h - py); p.vertex(0, py);
        }
        p.endShape(p.CLOSE);
    }

    if (isNegated) {
        p.fill(COLOR_COMPONENT_BG); p.circle(gateW - bubbleR, h / 2, bubbleR*2);
    }
  }

  private static drawLabels(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      if (comp.customLabel && comp.type !== ComponentType.CUSTOM_IC) {
        p.noStroke(); p.fill('#1e293b'); p.textSize(12); p.textStyle(p.BOLD);
        p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2);
        p.textStyle(p.NORMAL);
      }
  }
}

import React, { useState, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas, { LogicCanvasHandle } from './components/LogicCanvas';
import BitViewer from './components/BitViewer';
import { ComponentType, CircuitComponent, FunctionCircuit, PortSide } from './types';
import { COMPONENT_DEFINITIONS } from './constants';
import { useProjectManager } from './hooks/useProjectManager';

const App: React.FC = () => {
  // -- UI State --
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(false);

  // Speed Control State
  const [speedSlider, setSpeedSlider] = useState(90); 
  const tickSpeed = speedSlider === 100 ? 0 : Math.max(1, 500 - (speedSlider * 5));
  const speedLabel = speedSlider === 100 ? "MAX" : `${tickSpeed}ms`;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newFuncName, setNewFuncName] = useState("");
  const [isProjectMenuOpen, setIsProjectMenuOpen] = useState(false);

  // -- Component Selection State --
  const [selectedComponent, setSelectedComponent] = useState<CircuitComponent | null>(null);
  const [tempLabel, setTempLabel] = useState("");

  // -- New: Bit Width Selection --
  const [selectedBitWidth, setSelectedBitWidth] = useState<number>(1);

  // -- Drag State --
  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [draggedFuncId, setDraggedFuncId] = useState<string | undefined>(undefined);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number, functionId?: string, bitWidth: number} | null>(null);

  // -- References --
  const canvasWrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<LogicCanvasHandle>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // -- Project Data Management --
  const {
      functions,
      activeFunctionId,
      activeFunction,
      lastSaved,
      dataVersion,
      switchToFunction,
      addFunction,
      deleteFunction,
      importData,
      clearData,
      persist
  } = useProjectManager(canvasRef);

  // -- Interactions --

  const handleTouchStartItem = (type: ComponentType, pos: {x: number, y: number}, functionId?: string) => {
    setDraggedType(type);
    setDraggedFuncId(functionId);
    setDragPos(pos);
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); 
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedType && dragPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left && dragPos.x <= rect.right &&
          dragPos.y >= rect.top && dragPos.y <= rect.bottom
        ) {
          setPendingDrop({ type: draggedType, x: dragPos.x - rect.left, y: dragPos.y - rect.top, functionId: draggedFuncId, bitWidth: selectedBitWidth });
        }
      }
      setDraggedType(null);
      setDraggedFuncId(undefined);
      setDragPos(null);
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }
    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, draggedFuncId, selectedBitWidth]); // Optimized deps

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const parsed = JSON.parse(e.target?.result as string);
            if (Array.isArray(parsed)) {
                if (confirm("Replace current project?")) {
                    importData(parsed, true);
                    setSelectedComponent(null);
                    setIsPlaying(false);
                }
            } else if (parsed.id) {
                importData(parsed, false);
                alert(`Imported: ${parsed.name}`);
            }
        } catch (err) { alert("Invalid File"); }
        if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsText(file);
  };

  const handleExport = (type: 'PROJECT' | 'FUNCTION') => {
      const data = type === 'PROJECT' 
        ? functions.map(f => f.id === activeFunctionId && canvasRef.current ? {...f, ...canvasRef.current.getData()} : f)
        : (canvasRef.current ? {...activeFunction, ...canvasRef.current.getData()} : activeFunction);

      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = type === 'PROJECT' ? `project.json` : `${activeFunction.name.replace(/\s+/g, '_')}.json`;
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      setIsProjectMenuOpen(false);
  };

  const createFunction = (e: React.FormEvent) => {
      e.preventDefault();
      if (newFuncName.trim()) {
          addFunction(newFuncName);
          setNewFuncName("");
          setIsModalOpen(false);
      }
  };

  const handleSelectionChange = (comp: CircuitComponent | null) => {
      setSelectedComponent(comp);
      if (comp) setTempLabel(comp.customLabel || "");
      else setTempLabel("");
  };

  const updateProp = (updates: Partial<CircuitComponent>) => {
    if (selectedComponent && canvasRef.current) {
        canvasRef.current.updateSelectedComponent(updates);
        setSelectedComponent(prev => prev ? { ...prev, ...updates } : null);
    }
  };

  // Track the ID in a ref to decouple the polling effect from selectedComponent state updates
  const selectedIdRef = useRef<string | null>(null);
  useEffect(() => { selectedIdRef.current = selectedComponent?.id || null; }, [selectedComponent]);

  // -- Live Monitor for Selected Component --
  useEffect(() => {
      if (!isPlaying) return;

      const interval = setInterval(() => {
          const currentId = selectedIdRef.current;
          if (!currentId || !canvasRef.current) return;

          const { components } = canvasRef.current.getData();
          const freshComp = components.find(c => c.id === currentId);

          if (freshComp) {
              setSelectedComponent(prev => {
                  // Guard against stale updates if selection changed
                  if (!prev || prev.id !== currentId) return prev;

                  // Deep compare key data values to avoid unnecessary re-renders
                  const prevHash = JSON.stringify({ i: prev.inputValues, o: prev.outputValues });
                  const newHash = JSON.stringify({ i: freshComp.inputValues, o: freshComp.outputValues });

                  if (prevHash !== newHash) {
                      return { ...freshComp };
                  }
                  // Return exact same object reference to prevent re-render
                  return prev;
              });
          }
      }, 100);

      return () => clearInterval(interval);
  }, [isPlaying]); 

  const handleBitToggle = (index: number) => {
      if (!selectedComponent || !canvasRef.current) return;

      const currentBus = selectedComponent.outputValues[0] || [];
      const newVal = !currentBus[index];

      canvasRef.current.setComponentOutputBit(selectedComponent.id, index, newVal);

      // Update local state immediately for responsiveness
      const newBus = [...currentBus];
      while(newBus.length <= index) newBus.push(false);
      newBus[index] = newVal;

      setSelectedComponent({ 
          ...selectedComponent, 
          outputValues: [newBus]
      });
  };

  const handleBatchBusChange = (newBus: boolean[]) => {
      if (!selectedComponent || !canvasRef.current) return;

      canvasRef.current.updateSelectedComponent({ outputValues: [newBus] });
      setSelectedComponent({ ...selectedComponent, outputValues: [newBus] });
  };

  return (
    <div className="fixed inset-0 flex bg-slate-50 text-slate-800 font-sans overflow-hidden select-none overscroll-none">
      <input type="file" ref={fileInputRef} onChange={handleFileImport} accept=".json" className="hidden" />

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={setSelectedTool}
        selectedBitWidth={selectedBitWidth}
        onSelectBitWidth={setSelectedBitWidth}
        onTouchStartItem={handleTouchStartItem}
        functionLibrary={functions}
      />

      <main className="flex-1 flex flex-col relative overflow-hidden">
        {/* HUD */}
        <div className="absolute top-4 left-4 right-4 bg-white/95 backdrop-blur shadow-sm rounded-md flex flex-wrap items-center justify-between px-4 py-2 z-10 border border-slate-200 gap-2 min-h-[50px]">

          <div className="flex items-center space-x-2">
             <div className="flex items-center bg-slate-100 rounded p-1 border border-slate-200">
               <span className="text-xs font-bold text-slate-400 px-2 hidden sm:inline">FUNC:</span>
               <select 
                 value={activeFunctionId}
                 onChange={(e) => { setIsPlaying(false); switchToFunction(e.target.value); }}
                 className="bg-transparent text-sm font-semibold text-slate-700 outline-none w-24 sm:w-32 cursor-pointer py-1"
               >
                 {functions.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
               </select>
               <button onClick={() => setIsModalOpen(true)} className="ml-2 w-8 h-8 bg-blue-100 text-blue-600 rounded hover:bg-blue-200 font-bold">+</button>
               {activeFunctionId !== 'main' && (
                 <button onClick={() => deleteFunction(activeFunctionId)} className="ml-1 w-8 h-8 bg-red-100 text-red-500 rounded hover:bg-red-200 font-bold">×</button>
               )}
             </div>

             <div className="h-5 w-px bg-slate-200 hidden sm:block"></div>

             <button 
               onClick={() => setIsPlaying(!isPlaying)}
               className={`px-4 py-1.5 rounded text-sm font-bold w-24 border ${isPlaying ? 'bg-orange-100 text-orange-600 border-orange-200' : 'bg-green-100 text-green-700 border-green-200'}`}
             >
               {isPlaying ? 'PAUSE' : 'RUN'}
             </button>

             {/* Speed Slider */}
             <div className="flex flex-col justify-center bg-slate-50 px-2 py-1 rounded border border-slate-200 w-24 sm:w-32">
                <div className="flex justify-between w-full mb-1">
                    <span className="text-[9px] font-bold text-slate-400">SPEED</span>
                    <span className="text-[9px] font-mono text-slate-500">{speedLabel}</span>
                </div>
                <input
                    type="range"
                    min="0"
                    max="100"
                    step="5"
                    value={speedSlider}
                    onChange={(e) => setSpeedSlider(Number(e.target.value))}
                    className="w-full h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-blue-500"
                    title="Simulation Speed"
                />
             </div>

             {/* Bit Viewer Injection */}
             {selectedComponent && selectedComponent.bitWidth >= 1 && (
                 <div className="hidden lg:block pl-2 border-l border-slate-200">
                    <BitViewer 
                      component={selectedComponent} 
                      onToggleBit={handleBitToggle} 
                      onChangeAll={handleBatchBusChange}
                    />
                 </div>
             )}

          </div>

          <div className="flex items-center space-x-3 w-full md:w-auto justify-end mt-2 md:mt-0">
             {selectedComponent && (
                 <div className="flex items-center space-x-2 flex-1 md:flex-none justify-center">
                     <button 
                         onClick={() => canvasRef.current?.focusComponent(selectedComponent.id)}
                         className="bg-white border border-slate-300 hover:bg-slate-50 text-slate-600 hover:text-slate-800 rounded px-2 py-1 text-xs font-bold shadow-sm transition-colors"
                         title="Center View on Selection"
                     >
                        Focus
                     </button>

                     {/* Port Side Selector for Inputs/Outputs */}
                     {(selectedComponent.type === ComponentType.INPUT_SWITCH || selectedComponent.type === ComponentType.OUTPUT_LED) && (
                       <div className="flex items-center bg-slate-50 px-2 py-1 rounded border border-slate-200">
                           <span className="text-[10px] font-bold text-slate-400 mr-1 uppercase">Side</span>
                           <select 
                               value={selectedComponent.icPortSide || (selectedComponent.type === 'INPUT' ? 'right' : 'left')}
                               onChange={(e) => updateProp({ icPortSide: e.target.value as PortSide })}
                               className="bg-transparent text-xs font-semibold text-slate-700 outline-none cursor-pointer"
                           >
                               <option value="left">Left</option>
                               <option value="right">Right</option>
                               <option value="top">Top</option>
                               <option value="bottom">Bottom</option>
                           </select>
                       </div>
                     )}

                     <div className="flex items-center bg-yellow-50 px-2 py-1 rounded border border-yellow-200">
                        <input 
                            type="text" 
                            value={tempLabel}
                            onChange={(e) => { setTempLabel(e.target.value); updateProp({ customLabel: e.target.value }); }}
                            className="bg-white border border-yellow-200 text-sm px-2 py-1 rounded w-24 focus:outline-none"
                            placeholder="Label"
                        />
                     </div>
                 </div>
             )}

             <div className="relative">
                <button onClick={() => setIsProjectMenuOpen(!isProjectMenuOpen)} className="px-3 py-2 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded text-sm font-semibold text-slate-700">
                    Project ▼
                </button>
                {isProjectMenuOpen && (
                    <div className="absolute top-full left-0 mt-2 w-56 bg-white rounded-lg shadow-xl border border-slate-100 py-2 z-50 flex flex-col">
                        <div className="px-4 py-2 text-xs text-slate-400 border-b mb-1">
                            {lastSaved ? `Saved: ${lastSaved.toLocaleTimeString()}` : 'Unsaved'}
                        </div>
                        <button onClick={() => { persist(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm hover:bg-slate-50">💾 Save Now</button>
                        <button onClick={() => { fileInputRef.current?.click(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📂 Import...</button>
                        <button onClick={() => handleExport('PROJECT')} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📦 Export All</button>
                        <button onClick={() => handleExport('FUNCTION')} className="px-4 py-2 text-left text-sm hover:bg-slate-50">📄 Export Active</button>
                        <div className="h-px bg-slate-100 my-1"></div>
                        <button onClick={() => { if(confirm("Clear all data?")) clearData(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50">🗑️ Reset</button>
                    </div>
                )}
                {isProjectMenuOpen && <div className="fixed inset-0 z-40" onClick={() => setIsProjectMenuOpen(false)}></div>}
             </div>
          </div>
        </div>

        {/* Canvas */}
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            key={`${activeFunctionId}-${dataVersion}`}
            ref={canvasRef}
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            initialComponents={activeFunction.components}
            initialWires={activeFunction.wires}
            functionLibrary={functions}
            onPendingDropHandled={() => setPendingDrop(null)}
            onSelectionChange={handleSelectionChange}
          />
        </div>

        {/* Drag Ghost */}
        {draggedType && dragPos && (
          <div className="fixed pointer-events-none z-50 opacity-80" style={{ left: dragPos.x, top: dragPos.y, transform: 'translate(-50%, -50%)' }}>
            <div className="w-12 h-12 bg-blue-100 border-2 border-blue-500 rounded flex items-center justify-center shadow-xl">
              <span className="text-[10px] font-bold text-blue-800">{draggedType === 'IC' ? 'IC' : COMPONENT_DEFINITIONS[draggedType].label}</span>
              <span className="absolute bottom-0 right-0 bg-blue-600 text-white text-[9px] px-1 rounded-tl">{selectedBitWidth}</span>
            </div>
          </div>
        )}

        {/* Modal */}
        {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden">
              <div className="bg-slate-50 px-4 py-3 border-b border-slate-100"><h3 className="font-bold">New Function</h3></div>
              <form onSubmit={createFunction} className="p-4">
                <input autoFocus type="text" value={newFuncName} onChange={(e) => setNewFuncName(e.target.value)} placeholder="Function Name" className="w-full px-3 py-2 border rounded-lg mb-4" />
                <div className="flex justify-end space-x-2">
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm font-bold text-slate-500">Cancel</button>
                  <button type="submit" className="px-4 py-2 text-sm font-bold text-white bg-blue-600 rounded-lg">Create</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;
